function isValidHttpUrl(str: string): boolean {
  try {
    const url = new URL(str);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
}

interface EndpointInput {
  api_type: "openai" | "openai-responses" | "anthropic";
  base_url: string;
  upstream_path?: string | null;
