    }
  }
  const processed = endpoints.map(e => ({
    api_type: e.api_type,
    base_url: e.base_url,
    upstream_path: e.upstream_path ?? null,
    api_key: e.api_key ? encrypt(e.api_key, encryptionKey) : null,
  }));
  return { ok: true, processed };
}

