export function deleteLogsBefore(db: Database.Database, beforeDate: string): number {
  const changes = db.prepare("DELETE FROM request_logs WHERE created_at < ?").run(beforeDate).changes;
  if (changes > 0) {
    db.pragma("incremental_vacuum");
  }
  return changes;
}

/** 每行元数据（数字列+索引）的估算字节数 */
const ROW_METADATA_BYTES = 500;

/** 采样估算 request_logs 表占用字节数（避免全表 SUM 扫描） */
export function estimateLogTableSize(db: Database.Database): number {
  const countRow = db.prepare("SELECT COUNT(*) as cnt FROM request_logs").get() as { cnt: number };
  if (countRow.cnt === 0) return 0;

  // 采样最近 100 行，计算平均行大小
  const samples = db.prepare(`
    SELECT COALESCE(length(client_request), 0) + COALESCE(length(upstream_request), 0) +
           COALESCE(length(upstream_response), 0) + COALESCE(length(stream_text_content), 0) +
           COALESCE(length(error_message), 0) + COALESCE(length(pipeline_snapshot), 0) + ? AS row_size
    FROM request_logs ORDER BY created_at DESC LIMIT 100
  `).all(ROW_METADATA_BYTES) as { row_size: number }[];

  const avgRowSize = samples.reduce((s, r) => s + r.row_size, 0) / samples.length;
  return Math.round(avgRowSize * countRow.cnt);
}

const DELETE_BATCH_SIZE = 1000;

/** 删除最旧的日志，保留 keepCount 条，返回实际删除条数。分批删除避免长时间锁表 */
export function deleteOldestLogs(db: Database.Database, keepCount: number): number {
  const total = (db.prepare("SELECT count(*) as c FROM request_logs").get() as { c: number }).c;
  const toDelete = Math.max(0, total - keepCount);
  if (toDelete === 0) return 0;

  let totalDeleted = 0;
  const stmt = db.prepare(`
    DELETE FROM request_logs
    WHERE rowid IN (
      SELECT rowid FROM request_logs ORDER BY created_at ASC LIMIT ?
    )
  `);

  while (totalDeleted < toDelete) {
    const batchSize = Math.min(DELETE_BATCH_SIZE, toDelete - totalDeleted);
    const result = stmt.run(batchSize);
    totalDeleted += result.changes;
    if (result.changes < batchSize) break;
  }

  if (totalDeleted > 0) {
    db.pragma("incremental_vacuum");
  }
  return totalDeleted;
}

/** 获取 request_logs 总行数 */
export function getLogCount(db: Database.Database): number {
  return (db.prepare("SELECT count(*) as c FROM request_logs").get() as { c: number }).c;
}

/** 查询某条日志的子请求（retry/failover 关联），上限 100 条 */
export function getRequestLogChildren(
  db: Database.Database,
  parentId: string,
): RequestLogListRow[] {
  return db.prepare(
    `SELECT ${LOG_LIST_SELECT}
     FROM request_logs rl
     ${LOG_LIST_JOIN}
     WHERE rl.original_request_id = ?
     ORDER BY rl.created_at ASC
     LIMIT 100`,
  ).all(parentId) as RequestLogListRow[];
}

export interface RequestLogGroupedRow extends RequestLogListRow {
  child_count: number;
}

/** 只返回根请求（original_request_id IS NULL），附带子请求数量 */
export function getRequestLogsGrouped(
  db: Database.Database,
  options: {
    page: number;
    limit: number;
    api_type?: string;
    model?: string;
    client_model?: string;
    backend_model?: string;
    router_key_id?: string;
    provider_id?: string;
    start_time?: string;
    end_time?: string;
  },
): { data: RequestLogGroupedRow[]; total: number } {
  const { where, params } = buildLogWhereClause(options, "rl.original_request_id IS NULL");
  const total = (
    db.prepare(`SELECT COUNT(*) as count FROM request_logs rl WHERE ${where}`).get(...params) as CountRow
  ).count;
  const offset = (options.page - 1) * options.limit;
  const data = db
    .prepare(
      `WITH page_ids AS (
         SELECT rl.id FROM request_logs rl
         ${LOG_LIST_JOIN}
         WHERE ${where}
         ORDER BY rl.created_at DESC LIMIT ? OFFSET ?
       )
       SELECT ${LOG_LIST_SELECT},
              COALESCE(child.cnt, 0) AS child_count
       FROM page_ids pg
       JOIN request_logs rl ON rl.id = pg.id
       ${LOG_LIST_JOIN}
       LEFT JOIN (
         SELECT original_request_id, COUNT(*) AS cnt
         FROM request_logs
         WHERE original_request_id IN (SELECT id FROM page_ids)
         GROUP BY original_request_id
       ) child ON child.original_request_id = rl.id
       ORDER BY rl.created_at DESC`,
    )
    .all(...params, options.limit, offset) as RequestLogGroupedRow[];
  return { data, total };
}

/** 后续 pipeline 阶段完成后，回写 snapshot 到已有日志 */
export function updateLogPipelineSnapshot(db: Database.Database, logId: string, snapshot: string): void {
  getCachedStmt(db, "UPDATE request_logs SET pipeline_snapshot = ? WHERE id = ?").run(snapshot, logId);
}

import { FastifyPluginCallback } from "fastify";
import Database from "better-sqlite3";
import { Type, Static } from "@sinclair/typebox";
import { getRequestLogs, getRequestLogsGrouped, getRequestLogById, getRequestLogChildren, deleteLogsBefore } from "../db/index.js";
import type { LogFileWriter } from "../storage/log-file-writer.js";
import { HTTP_NOT_FOUND } from "./constants.js";
import { API_CODE, apiError } from "./api-response.js";

const LogQuerySchema = Type.Object({
  page: Type.Optional(Type.String()),
  limit: Type.Optional(Type.String()),
  api_type: Type.Optional(Type.String()),
  model: Type.Optional(Type.String()),
  client_model: Type.Optional(Type.String()),
  backend_model: Type.Optional(Type.String()),
  router_key_id: Type.Optional(Type.String()),
  provider_id: Type.Optional(Type.String()),
  start_time: Type.Optional(Type.String()),
  end_time: Type.Optional(Type.String()),
  status_code: Type.Optional(Type.String()),
  view: Type.Optional(Type.Literal("grouped")),
});

const DeleteLogsBeforeSchema = Type.Object({
  before: Type.String({ minLength: 1 }),
});

const DEFAULT_LOG_VIEW = "flat";

interface LogRoutesOptions {
  db: Database.Database;
  logFileWriter?: LogFileWriter | null;
}

export const adminLogRoutes: FastifyPluginCallback<LogRoutesOptions> = (app, options, done) => {
  const { db, logFileWriter } = options;

  app.get("/admin/api/logs", { schema: { querystring: LogQuerySchema } }, async (request, reply) => {
    const query = request.query as Static<typeof LogQuerySchema>;
    const page = parseInt(query.page || "1", 10);
    const limit = parseInt(query.limit || "20", 10);
    const view = query.view || DEFAULT_LOG_VIEW;

    const listOptions = {
      page,
      limit,
      api_type: query.api_type || undefined,
      model: query.model || undefined,
      client_model: query.client_model || undefined,
      backend_model: query.backend_model || undefined,
      router_key_id: query.router_key_id || undefined,
      provider_id: query.provider_id || undefined,
      start_time: query.start_time || undefined,
      end_time: query.end_time || undefined,
      status_code: query.status_code || undefined,
    };

    const result = view === "grouped"
      ? getRequestLogsGrouped(db, listOptions)
      : getRequestLogs(db, listOptions);
    return reply.send({ ...result, page, limit });
  });

  app.get("/admin/api/logs/:id", async (request, reply) => {
    const params = request.params as { id: string };
    const log = getRequestLogById(db, params.id);
    if (!log) {
      return reply.code(HTTP_NOT_FOUND).send(apiError(API_CODE.NOT_FOUND, "Log not found"));
    }

    // DB 字段为 null 时，从 JSONL 文件回填详情
    const needsBackfill = log.client_request === null || log.upstream_request === null || log.upstream_response === null;
    if (needsBackfill && logFileWriter && logFileWriter.isEnabled && log.created_at) {
      const fileEntry = logFileWriter.read(log.id, log.created_at);
      if (fileEntry) {
        if (log.client_request === null && fileEntry.client_request !== null) {
          log.client_request = fileEntry.client_request;
        }
        if (log.upstream_request === null && fileEntry.upstream_request !== null) {
          log.upstream_request = fileEntry.upstream_request;
        }
        if (log.upstream_response === null && fileEntry.upstream_response !== null) {
          log.upstream_response = fileEntry.upstream_response;
        }
      }
    }

    // JSONL 回填后重新提取 thinking level（覆盖 SQL 层因 client_request 为 null 得出的 'off'）
    if (log.client_request) {
      try {
        const parsed = JSON.parse(log.client_request);
        const body = parsed?.body;
        if (body) {
          if (log.api_type === "anthropic") {
            if (body.thinking?.type) log.thinking_level = body.thinking.type;
          } else {
            log.thinking_level = body.reasoning?.effort ?? body.reasoning_effort ?? "off";
          }
        }
      } catch {
        log.thinking_level = "off";
      }
    }

    return reply.send(log);
  });

  app.get("/admin/api/logs/:id/children", async (request, reply) => {
    const params = request.params as { id: string };
    const parent = getRequestLogById(db, params.id);
    if (!parent) {
      return reply.code(HTTP_NOT_FOUND).send(apiError(API_CODE.NOT_FOUND, "Log not found"));
    }
    const rows = getRequestLogChildren(db, params.id);
    return reply.send(rows);
  });

  app.delete("/admin/api/logs/before", { schema: { body: DeleteLogsBeforeSchema } }, async (request, reply) => {
    const body = request.body as Static<typeof DeleteLogsBeforeSchema>;
    const deleted = deleteLogsBefore(db, body.before);
    return reply.send({ deleted });
  });

  done();
};

import { decrypt } from "../../utils/crypto.js";
import { parseEndpoints } from "../../db/providers.js";
import type { Provider } from "../../db/providers.js";
import type { ProviderEndpoint, ResolvedEndpoint } from "../../core/types.js";

export type ApiType = "openai" | "openai-responses" | "anthropic";

export function resolveEndpoint(
  provider: Provider,
  clientApiType: ApiType,
  encryptionKey: string,
): ResolvedEndpoint {
  const endpoints = parseEndpoints(provider.endpoints);

  if (endpoints.length === 0) {
    throw new Error(`Provider ${provider.id} has no endpoints`);
  }

  const matched = endpoints.find((ep) => ep.api_type === clientApiType);
  let endpoint: ProviderEndpoint;
  let needsTransform: boolean;

  if (matched) {
    endpoint = matched;
    needsTransform = false;
  } else {
    endpoint = endpoints[0];
    needsTransform = endpoint.api_type !== clientApiType;
  }

  // api_key: endpoint 独立 key > provider 共享 key
  const rawKey = endpoint.api_key ?? provider.api_key;
  const decryptedKey = decrypt(rawKey, encryptionKey);

  return {
    api_type: endpoint.api_type,
    base_url: endpoint.base_url,
    upstream_path: endpoint.upstream_path ?? null,
    api_key: decryptedKey,
    needs_transform: needsTransform,
  };
}

