// src/core/types.ts
// 被多个目录（proxy, db, monitor, admin）共享的类型定义

// Re-export ConcurrencyConfig from merged core
export type { ConcurrencyConfig } from "./concurrency/types.js";

/** Generic logger interface for core package decoupling from pino/fastify. */
export interface Logger {
  debug?(obj: Record<string, unknown>, msg: string): void;
  info?(obj: Record<string, unknown>, msg: string): void;
  warn?(obj: Record<string, unknown>, msg: string): void;
  error?(obj: Record<string, unknown>, msg: string): void;
}

// ========== 来自原 proxy/strategy/types.ts ==========

export interface Target {
  backend_model: string;
  provider_id: string;
  overflow_provider_id?: string;
  overflow_model?: string;
}

export interface ResolveContext {
  now: Date;
  excludeTargets?: Target[];
}

export interface ConcurrencyOverride {
  max_concurrency?: number;
  queue_timeout_ms?: number;
  max_queue_size?: number;
}

export type MappingReason =
  | "direct_format"
  | "group_base_rule"
  | "group_schedule"
  | "fallback_provider"
  | "overflow_redirect"
  | "failover_retry";

export interface ResolveResult {
  target: Target;
  concurrency_override?: ConcurrencyOverride;
  /** 活跃规则（schedule 或 base）中的 target 总数，用于 failover 判断 */
  targetCount: number;
  /** 排除前的完整 target 列表，用于请求级缓存（BP-H2） */
  allTargets?: Target[];
  /** 映射解析原因，标识走了哪条解析路径 */
  mappingReason: MappingReason;
}

// ========== 来自原 proxy/types.ts 公共部分 ==========

// ========== 来自原 metrics/metrics-extractor.ts ==========

export interface MetricsResult {
  input_tokens: number | null;
  output_tokens: number | null;
  cache_creation_tokens: number | null;
  cache_read_tokens: number | null;
  cache_read_tokens_estimated?: number;
  ttft_ms: number | null;
  /** T6 - T0: proxy end-to-end streaming duration */
  total_duration_ms: number | null;
  /** @deprecated Use total_tps instead */
  tokens_per_second: number | null;
  stop_reason: string | null;
  is_complete: number;
  input_tokens_estimated?: number;
  // --- Two-phase TPS: thinking / non-thinking ---
  thinking_tokens: number | null;
  /** T3 - T0: request start to last thinking delta */
  thinking_duration_ms: number | null;
  thinking_tps: number | null;
  /** T6 - T3 (thinking) or T6 - T0 (non-thinking) */
  non_thinking_duration_ms: number | null;
  non_thinking_tps: number | null;
  total_tps: number | null;
  // --- Content counts (for analysis, not TPS) ---
  text_tokens: number | null;
  tool_use_tokens: number | null;
}

// ========== 来自原 proxy/types.ts 公共部分 ==========

export type RawHeaders = Record<string, string | string[] | undefined>;

export type TransportResult =
  | {
      kind: "success";
      statusCode: number;
      body: string;
      headers: Record<string, string>;
      sentHeaders: Record<string, string>;
      sentBody: string;
    }
  | {
      kind: "stream_success";
      statusCode: number;
      metrics?: MetricsResult;
      upstreamResponseHeaders?: Record<string, string>;
      sentHeaders: Record<string, string>;
    }
  | {
      kind: "stream_error";
      statusCode: number;
      body: string;
      headers: Record<string, string>;
      sentHeaders: Record<string, string>;
      headersSent?: boolean;
    }
  | {
      kind: "stream_abort";
      statusCode: number;
      metrics?: MetricsResult;
      upstreamResponseHeaders?: Record<string, string>;
      sentHeaders: Record<string, string>;
      timeoutContext?: { modelId: string; providerId: string };
      timeoutMs?: number;
      abortReason?: "idle_timeout" | "client_disconnect" | "loop_detection";
    }
  | {
      kind: "error";
      statusCode: number;
      body: string;
      headers: Record<string, string>;
      sentHeaders: Record<string, string>;
      sentBody: string;
    }
  | {
      kind: "throw";
      error: Error;
      headersSent?: boolean;
    };

/** 单次 resilience 尝试的记录 */
export interface ResilienceAttempt {
  target: Target;
  attemptIndex: number;
  statusCode: number | null;
  error: string | null;
  latencyMs: number;
  responseBody: string | null;
  /** 上游响应 headers（throw 和 stream_success/stream_abort 时为 null） */
  responseHeaders: Record<string, string> | null;
  /** TransportResult.kind，用于区分 stream_error 等特殊类型 */
  resultKind: TransportResult["kind"];
  /** error.code（如 ETIMEDOUT / ECONNRESET / ECONNREFUSED），仅 throw 时有值 */
  error_code?: string | null;
  /** response headers 是否已发送，影响重试/failover 决策 */
  headers_sent?: boolean | null;
}

/** Provider endpoint — stored in providers.endpoints JSON field */
export interface ProviderEndpoint {
  api_type: "openai" | "openai-responses" | "anthropic";
  base_url: string;
  upstream_path?: string | null;
  api_key?: string | null; // null = fallback 到 provider.api_key
}

/** resolveEndpoint() 的输出 — 所有下游消费者只消费此对象 */
export interface ResolvedEndpoint {
  api_type: "openai" | "openai-responses" | "anthropic";
  base_url: string;
  upstream_path: string | null;
  api_key: string; // 已解密的最终 key（永远不会是 null）
  needs_transform: boolean; // 是否需要 FormatRegistry 格式转换
}

/** 流式传输阶段状态 */
export type StreamState =
  | "BUFFERING"
  | "STREAMING"
  | "COMPLETED"
  | "EARLY_ERROR"
  | "ABORTED";

import Database from "better-sqlite3";
import { randomUUID } from "crypto";
import { buildUpdateQuery, deleteById } from "./helpers.js";
import { parseModels } from "../config/model-context.js";
import type { ProviderEndpoint } from "../core/types.js";

export interface Provider {
  id: string;
  name: string;
  api_type: "openai" | "openai-responses" | "anthropic";
  base_url: string;
  upstream_path: string | null;
  api_key: string;
  api_key_preview?: string;
  /** @internal 原始 JSON 文本，业务层请使用 parseModels() 解析，禁止直接 JSON.parse */
  models: string;
  is_active: number;
  max_concurrency: number;
  queue_timeout_ms: number;
  max_queue_size: number;
  adaptive_enabled: number;
  proxy_type: string | null;
  proxy_url: string | null;
  proxy_username: string | null;
  proxy_password: string | null;
  /** @internal 原始 JSON 文本，业务层用 parseEndpoints() 解析 */
  endpoints?: string;
  created_at: string;
  updated_at: string;
}

/** 默认流式超时 10 分钟 */
export const DEFAULT_STREAM_TIMEOUT_MS = 600_000;

/** 从 provider 的 models JSON 中查找指定模型的超时值 */
export function getModelStreamTimeout(
  provider: Provider,
  backendModel: string,
): number {
  const entries = parseModels(provider.models);
  const entry = entries.find(m => m.name === backendModel);
  if (!entry) return DEFAULT_STREAM_TIMEOUT_MS;
  const timeout = entry.stream_timeout_ms;
  // stream_timeout_ms: 0 表示禁用超时，返回 Infinity；
  // undefined/null/未设置 表示使用默认值
  if (timeout === 0) return Number.POSITIVE_INFINITY;
  return timeout ?? DEFAULT_STREAM_TIMEOUT_MS;
}

export const PROVIDER_CONCURRENCY_DEFAULTS = {
  max_concurrency: 0,
  queue_timeout_ms: 0,
  max_queue_size: 100,
} as const;

const PROVIDER_FIELDS = new Set([
  "name", "api_type", "base_url", "upstream_path", "api_key", "api_key_preview", "models", "is_active", "max_concurrency", "queue_timeout_ms", "max_queue_size", "adaptive_enabled", "proxy_type", "proxy_url", "proxy_username", "proxy_password", "endpoints",
]);

/** 解析 endpoints JSON 文本为类型安全的数组 */
export function parseEndpoints(endpointsJson: string | null | undefined): ProviderEndpoint[] {
  if (!endpointsJson) return [];
  const parsed: unknown[] = JSON.parse(endpointsJson) as unknown[];
  if (!Array.isArray(parsed)) {
    throw new Error(`Invalid endpoints JSON: not an array`);
  }
  // Validate every element is a non-null object with api_type and base_url
  for (const item of parsed) {
    if (item === null || typeof item !== "object" || Array.isArray(item)) {
      throw new Error(`Invalid endpoints JSON: contains non-object element`);
    }
  }
  return parsed as ProviderEndpoint[];
}

/** 将 endpoints 数组序列化为 JSON 文本（用于 DB 写入） */
export function serializeEndpoints(endpoints: ProviderEndpoint[]): string {
  return JSON.stringify(endpoints);
}

export function getActiveProviders(
  db: Database.Database,
  apiType: "openai" | "openai-responses" | "anthropic",
): Provider[] {
  return db
    .prepare("SELECT * FROM providers WHERE api_type = ? AND is_active = 1")
    .all(apiType) as Provider[];
}

export function getAllProviders(db: Database.Database): Provider[] {
  return db.prepare("SELECT * FROM providers ORDER BY created_at DESC").all() as Provider[];
}

export function getProviderById(db: Database.Database, id: string): Provider | undefined {
  return db.prepare("SELECT * FROM providers WHERE id = ?").get(id) as Provider | undefined;
}

export function createProvider(
  db: Database.Database,
  provider: {
    name: string;
    api_type: "openai" | "openai-responses" | "anthropic";
    base_url: string;
    upstream_path?: string | null;
    api_key: string;
    api_key_preview?: string;
    models?: string;
    is_active?: number;
    max_concurrency?: number;
    queue_timeout_ms?: number;
    max_queue_size?: number;
    adaptive_enabled?: number;
    proxy_type?: string | null;
    proxy_url?: string | null;
    proxy_username?: string | null;
    proxy_password?: string | null;
    endpoints?: string;
  },
): string {
  const id = randomUUID();
  const now = new Date().toISOString();
  db.prepare(
    `INSERT INTO providers (id, name, api_type, base_url, upstream_path, api_key, api_key_preview, models, is_active, max_concurrency, queue_timeout_ms, max_queue_size, adaptive_enabled, proxy_type, proxy_url, proxy_username, proxy_password, endpoints, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).run(
    id, provider.name, provider.api_type, provider.base_url,
    provider.upstream_path ?? null,
    provider.api_key, provider.api_key_preview ?? null,
    provider.models ?? "[]",
    provider.is_active ?? 1,
    provider.max_concurrency ?? PROVIDER_CONCURRENCY_DEFAULTS.max_concurrency,
    provider.queue_timeout_ms ?? PROVIDER_CONCURRENCY_DEFAULTS.queue_timeout_ms,
    provider.max_queue_size ?? PROVIDER_CONCURRENCY_DEFAULTS.max_queue_size,
    provider.adaptive_enabled ?? 0,
    provider.proxy_type ?? null,
    provider.proxy_url ?? null,
    provider.proxy_username ?? null,
    provider.proxy_password ?? null,
    provider.endpoints ?? null,
    now, now,
  );
  return id;
}

export function updateProvider(
  db: Database.Database,
  id: string,
  fields: Partial<Pick<Provider, "name" | "api_type" | "base_url" | "upstream_path" | "api_key" | "api_key_preview" | "models" | "is_active" | "max_concurrency" | "queue_timeout_ms" | "max_queue_size" | "adaptive_enabled" | "proxy_type" | "proxy_url" | "proxy_username" | "proxy_password" | "endpoints">>,
): void {
  buildUpdateQuery(db, "providers", id, fields, PROVIDER_FIELDS, { updatedAt: true });
}

export function deleteProvider(db: Database.Database, id: string): void {
  deleteById(db, "providers", id);
}

export function getActiveProviderByName(db: Database.Database, name: string): { id: string; models: string } | undefined {
  return db.prepare("SELECT id, models FROM providers WHERE name = ? AND is_active = 1").get(name) as { id: string; models: string } | undefined;
}

export function getActiveProvidersWithModels(db: Database.Database): { id: string; name: string; models: string }[] {
  return db.prepare("SELECT id, name, models FROM providers WHERE is_active = 1").all() as { id: string; name: string; models: string }[];
}

import { decrypt } from "../../utils/crypto.js";
import { parseEndpoints } from "../../db/providers.js";
import type { Provider } from "../../db/providers.js";
import type { ProviderEndpoint, ResolvedEndpoint } from "../../core/types.js";

export type ApiType = "openai" | "openai-responses" | "anthropic";

export function resolveEndpoint(
  provider: Provider,
  clientApiType: ApiType,
  encryptionKey: string,
): ResolvedEndpoint {
  const endpoints = parseEndpoints(provider.endpoints);

  // Legacy provider without endpoints JSON: fall back to provider-level fields
  if (endpoints.length === 0) {
    const rawKey = provider.api_key;
    const decryptedKey = decrypt(rawKey, encryptionKey);
    return {
      api_type: provider.api_type,
      base_url: provider.base_url,
      upstream_path: provider.upstream_path ?? null,
      api_key: decryptedKey,
      needs_transform: provider.api_type !== clientApiType,
    };
  }

  const matched = endpoints.find((ep) => ep.api_type === clientApiType);
  let endpoint: ProviderEndpoint;
  let needsTransform: boolean;

  if (matched) {
    endpoint = matched;
    needsTransform = false;
  } else {
    endpoint = endpoints[0];
    needsTransform = endpoint.api_type !== clientApiType;
  }

  // api_key: endpoint 独立 key > provider 共享 key
  const rawKey = endpoint.api_key ?? provider.api_key;
  const decryptedKey = decrypt(rawKey, encryptionKey);

  return {
    api_type: endpoint.api_type,
    base_url: endpoint.base_url,
    upstream_path: endpoint.upstream_path ?? null,
    api_key: decryptedKey,
    needs_transform: needsTransform,
  };
}

