}

/** 当 router 返回给客户端的 status code 与上游不同时，记录实际发送的 status */
export function updateLogClientStatus(db: Database.Database, logId: string, clientStatusCode: number): void {
  getCachedStmt(db, "UPDATE request_logs SET client_status_code = ? WHERE id = ?").run(clientStatusCode, logId);
}



export function deleteLogsBefore(db: Database.Database, beforeDate: string): number {
  const changes = db.prepare("DELETE FROM request_logs WHERE created_at < ?").run(beforeDate).changes;
  if (changes > 0) {
    db.pragma("incremental_vacuum");
  }
  return changes;
}

/** 每行元数据（数字列+索引）的估算字节数 */
const ROW_METADATA_BYTES = 500;

/** 采样估算 request_logs 表占用字节数（避免全表 SUM 扫描） */
export function estimateLogTableSize(db: Database.Database): number {
  const countRow = db.prepare("SELECT COUNT(*) as cnt FROM request_logs").get() as { cnt: number };
  if (countRow.cnt === 0) return 0;

  // 采样最近 100 行，计算平均行大小
  const samples = db.prepare(`
    SELECT COALESCE(length(client_request), 0) + COALESCE(length(upstream_request), 0) +
           COALESCE(length(upstream_response), 0) + COALESCE(length(stream_text_content), 0) +
           COALESCE(length(error_message), 0) + COALESCE(length(pipeline_snapshot), 0) + ? AS row_size
    FROM request_logs ORDER BY created_at DESC LIMIT 100
  `).all(ROW_METADATA_BYTES) as { row_size: number }[];

  const avgRowSize = samples.reduce((s, r) => s + r.row_size, 0) / samples.length;
  return Math.round(avgRowSize * countRow.cnt);
}

const DELETE_BATCH_SIZE = 1000;

/** 删除最旧的日志，保留 keepCount 条，返回实际删除条数。分批删除避免长时间锁表 */
export function deleteOldestLogs(db: Database.Database, keepCount: number): number {
  const total = (db.prepare("SELECT count(*) as c FROM request_logs").get() as { c: number }).c;
  const toDelete = Math.max(0, total - keepCount);
  if (toDelete === 0) return 0;

  let totalDeleted = 0;
  const stmt = db.prepare(`
    DELETE FROM request_logs
    WHERE rowid IN (
      SELECT rowid FROM request_logs ORDER BY created_at ASC LIMIT ?
    )
  `);

  while (totalDeleted < toDelete) {
    const batchSize = Math.min(DELETE_BATCH_SIZE, toDelete - totalDeleted);
    const result = stmt.run(batchSize);
    totalDeleted += result.changes;
    if (result.changes < batchSize) break;
  }

  if (totalDeleted > 0) {
    db.pragma("incremental_vacuum");
  }
  return totalDeleted;
}

/** 获取 request_logs 总行数 */
export function getLogCount(db: Database.Database): number {
  return (db.prepare("SELECT count(*) as c FROM request_logs").get() as { c: number }).c;
}

/** 查询某条日志的子请求（retry/failover 关联），上限 100 条 */
export function getRequestLogChildren(
  db: Database.Database,
  parentId: string,
): RequestLogListRow[] {
  return db.prepare(
    `SELECT ${LOG_LIST_SELECT}
     FROM request_logs rl
     ${LOG_LIST_JOIN}
     WHERE rl.original_request_id = ?
     ORDER BY rl.created_at ASC
     LIMIT 100`,
  ).all(parentId) as RequestLogListRow[];
}

export interface RequestLogGroupedRow extends RequestLogListRow {
  child_count: number;
}

/** 只返回根请求（original_request_id IS NULL），附带子请求数量 */
export function getRequestLogsGrouped(
  db: Database.Database,
  options: {
    page: number;
    limit: number;
    api_type?: string;
    model?: string;
    client_model?: string;
    backend_model?: string;
    router_key_id?: string;
    provider_id?: string;
    start_time?: string;
    end_time?: string;
  },
): { data: RequestLogGroupedRow[]; total: number } {
  const { where, params } = buildLogWhereClause(options, "rl.original_request_id IS NULL");
  const total = (
    db.prepare(`SELECT COUNT(*) as count FROM request_logs rl WHERE ${where}`).get(...params) as CountRow
  ).count;
  const offset = (options.page - 1) * options.limit;
  const data = db
    .prepare(
      `WITH page_ids AS (
         SELECT rl.id FROM request_logs rl
         ${LOG_LIST_JOIN}
         WHERE ${where}
         ORDER BY rl.created_at DESC LIMIT ? OFFSET ?
       )
       SELECT ${LOG_LIST_SELECT},
              COALESCE(child.cnt, 0) AS child_count
       FROM page_ids pg
       JOIN request_logs rl ON rl.id = pg.id
       ${LOG_LIST_JOIN}
       LEFT JOIN (
         SELECT original_request_id, COUNT(*) AS cnt
         FROM request_logs
         WHERE original_request_id IN (SELECT id FROM page_ids)
         GROUP BY original_request_id
       ) child ON child.original_request_id = rl.id
       ORDER BY rl.created_at DESC`,
    )
    .all(...params, options.limit, offset) as RequestLogGroupedRow[];
  return { data, total };
}

/** 后续 pipeline 阶段完成后，回写 snapshot 到已有日志 */
export function updateLogPipelineSnapshot(db: Database.Database, logId: string, snapshot: string): void {
  getCachedStmt(db, "UPDATE request_logs SET pipeline_snapshot = ? WHERE id = ?").run(snapshot, logId);
}

import { FastifyPluginCallback } from "fastify";
import Database from "better-sqlite3";
import { Type, Static } from "@sinclair/typebox";
import { getRequestLogs, getRequestLogsGrouped, getRequestLogById, getRequestLogChildren, deleteLogsBefore } from "../db/index.js";
import type { LogFileWriter } from "../storage/log-file-writer.js";
import { HTTP_NOT_FOUND } from "./constants.js";
import { API_CODE, apiError } from "./api-response.js";

const LogQuerySchema = Type.Object({
  page: Type.Optional(Type.String()),
  limit: Type.Optional(Type.String()),
  api_type: Type.Optional(Type.String()),
  model: Type.Optional(Type.String()),
  client_model: Type.Optional(Type.String()),
  backend_model: Type.Optional(Type.String()),
  router_key_id: Type.Optional(Type.String()),
  provider_id: Type.Optional(Type.String()),
  start_time: Type.Optional(Type.String()),
  end_time: Type.Optional(Type.String()),
  status_code: Type.Optional(Type.String()),
  view: Type.Optional(Type.Literal("grouped")),
});

const DeleteLogsBeforeSchema = Type.Object({
  before: Type.String({ minLength: 1 }),
});

const DEFAULT_LOG_VIEW = "flat";

interface LogRoutesOptions {
  db: Database.Database;
  logFileWriter?: LogFileWriter | null;
}

export const adminLogRoutes: FastifyPluginCallback<LogRoutesOptions> = (app, options, done) => {
  const { db, logFileWriter } = options;

  app.get("/admin/api/logs", { schema: { querystring: LogQuerySchema } }, async (request, reply) => {
    const query = request.query as Static<typeof LogQuerySchema>;
    const page = parseInt(query.page || "1", 10);
    const limit = parseInt(query.limit || "20", 10);
    const view = query.view || DEFAULT_LOG_VIEW;

    const listOptions = {
      page,
      limit,
      api_type: query.api_type || undefined,
      model: query.model || undefined,
      client_model: query.client_model || undefined,
      backend_model: query.backend_model || undefined,
      router_key_id: query.router_key_id || undefined,
      provider_id: query.provider_id || undefined,
      start_time: query.start_time || undefined,
      end_time: query.end_time || undefined,
      status_code: query.status_code || undefined,
    };

    const result = view === "grouped"
      ? getRequestLogsGrouped(db, listOptions)
      : getRequestLogs(db, listOptions);
    return reply.send({ ...result, page, limit });
  });

  app.get("/admin/api/logs/:id", async (request, reply) => {
    const params = request.params as { id: string };
    const log = getRequestLogById(db, params.id);
    if (!log) {
      return reply.code(HTTP_NOT_FOUND).send(apiError(API_CODE.NOT_FOUND, "Log not found"));
    }

    // DB 字段为 null 时，从 JSONL 文件回填详情
    const needsBackfill = log.client_request === null || log.upstream_request === null || log.upstream_response === null;
    if (needsBackfill && logFileWriter && logFileWriter.isEnabled && log.created_at) {
      const fileEntry = logFileWriter.read(log.id, log.created_at);
      if (fileEntry) {
        if (log.client_request === null && fileEntry.client_request !== null) {
          log.client_request = fileEntry.client_request;
        }
        if (log.upstream_request === null && fileEntry.upstream_request !== null) {
          log.upstream_request = fileEntry.upstream_request;
        }
        if (log.upstream_response === null && fileEntry.upstream_response !== null) {
          log.upstream_response = fileEntry.upstream_response;
        }
      }
    }

    // JSONL 回填后重新提取 thinking level（覆盖 SQL 层因 client_request 为 null 得出的 'off'）
    if (log.client_request) {
      try {
        const parsed = JSON.parse(log.client_request);
        const body = parsed?.body;
        if (body) {
          if (log.api_type === "anthropic") {
            if (body.thinking?.type) log.thinking_level = body.thinking.type;
          } else {
            log.thinking_level = body.reasoning?.effort ?? body.reasoning_effort ?? "off";
          }
        }
      } catch {
        log.thinking_level = "off";
      }
    }

    return reply.send(log);
  });

  app.get("/admin/api/logs/:id/children", async (request, reply) => {
    const params = request.params as { id: string };
    const parent = getRequestLogById(db, params.id);
    if (!parent) {
      return reply.code(HTTP_NOT_FOUND).send(apiError(API_CODE.NOT_FOUND, "Log not found"));
    }
    const rows = getRequestLogChildren(db, params.id);
    return reply.send(rows);
  });

  app.delete("/admin/api/logs/before", { schema: { body: DeleteLogsBeforeSchema } }, async (request, reply) => {
    const body = request.body as Static<typeof DeleteLogsBeforeSchema>;
    const deleted = deleteLogsBefore(db, body.before);
    return reply.send({ deleted });
  });

  done();
};

import { ref, computed } from "vue";
import { useI18n } from "vue-i18n";
import * as z from "zod";
import type { ProviderPayload } from "@/api/client";
import type { Provider, ModelInfo, ProviderEndpoint } from "@/types/mapping";
import { DEFAULT_CONTEXT_WINDOW, DEFAULT_STREAM_TIMEOUT_MS } from "@/constants";
import type { ModelConfig } from "@/components/quick-setup/types";
import { useTransformRules } from "@/composables/useTransformRules";
import { useProviderPresets } from "@/composables/useProviderPresets";
import type { ConcurrencyMode } from "@/types/concurrency";

const DEFAULT_CONCURRENCY = 3;
const DEFAULT_CONCURRENCY_AUTO = 10;
const DEFAULT_QUEUE_TIMEOUT_MS = 120_000;
const DEFAULT_QUEUE_SIZE = 10;
const MAX_CONCURRENCY = 100;
const MAX_QUEUE_SIZE = 1000;
const CONTEXT_K = 1000;
const CONTEXT_M = 1_000_000;
const MS_PER_SECOND = 1000;

interface FormState {
  name: string;
  api_type: string;
  base_url: string;
  upstream_path: string;
  api_key: string;
  endpoints: ProviderEndpoint[];
  models: ModelInfo[];
  is_active: boolean;
  max_concurrency: number;
  queue_timeout_ms: number;
  max_queue_size: number;
  adaptive_enabled: boolean;
  proxy_type: string;
  proxy_url: string;
  proxy_username: string;
  proxy_password: string;
}

const DEFAULT_FORM: FormState = {
  name: "",
  api_type: "anthropic",
  base_url: "",
  upstream_path: "",
  api_key: "",
  endpoints: [],
  models: [],
  is_active: true,
  max_concurrency: DEFAULT_CONCURRENCY_AUTO,
  queue_timeout_ms: DEFAULT_QUEUE_TIMEOUT_MS,
  max_queue_size: DEFAULT_QUEUE_SIZE,
  adaptive_enabled: true,
  proxy_type: "",
  proxy_url: "",
  proxy_username: "",
  proxy_password: "",
};

const CONTEXT_WINDOW_OPTIONS = [
  { label: "8K", value: "8000" },
  { label: "16K", value: "16000" },
  { label: "32K", value: "32000" },
  { label: "64K", value: "64000" },
  { label: "128K", value: "128000" },
  { label: "160K", value: "160000" },
  { label: "200K", value: "200000" },
  { label: "256K", value: "256000" },
  { label: "1M", value: "1000000" },
] as const;

export const API_TYPE_LABELS: Record<string, string> = {
  openai: "OpenAI Chat Completions",
  "openai-responses": "OpenAI Responses",
  anthropic: "Anthropic Messages",
};

export { CONTEXT_WINDOW_OPTIONS, MS_PER_SECOND, CONTEXT_K, CONTEXT_M };

type ProviderFormPayload = Pick<
  ProviderPayload,
  | "name"
  | "api_type"
  | "base_url"
  | "upstream_path"
  | "models"
  | "is_active"
  | "max_concurrency"
  | "queue_timeout_ms"
  | "max_queue_size"
  | "adaptive_enabled"
  | "proxy_type"
  | "proxy_url"
  | "proxy_username"
  | "proxy_password"
  | "endpoints"
> & { api_key?: string };

export function useProviderForm() {
  const { t } = useI18n();
  const { transformForm, loadTransformRules, saveTransformRules } =
    useTransformRules();

  const form = ref<FormState>({ ...DEFAULT_FORM });
  const errors = ref<Record<string, string>>({});
  const concurrencyMode = ref<ConcurrencyMode>("auto");
  const dialogOpen = ref(false);
  const editingId = ref<string | null>(null);
  const modelInput = ref("");
  const modelContextWindow = ref(DEFAULT_CONTEXT_WINDOW);
  const contextWindowSelect = computed({
    get: () => `${modelContextWindow.value}`,
    set: (val: string) => {
      modelContextWindow.value = Number(val);
    },
  });

  const presetHook = useProviderPresets(form);

  function validate(): boolean {
    const schema = z.object({
      name: z
        .string()
        .min(1, t("providers.validation.nameRequired"))
        .regex(/^[a-zA-Z0-9_-]+$/, t("providers.validation.namePattern")),
      base_url: z
        .string()
        .min(1, t("providers.validation.baseUrlRequired"))
        .url(t("providers.validation.baseUrlInvalid")),
    });
    const errs: Record<string, string> = {};
    const result = schema.safeParse({
      name: form.value.name.trim(),
      base_url: form.value.base_url.trim(),
    });
    if (!result.success) {
      for (const issue of result.error.issues) {
        const field = issue.path[0] as string;
        if (!errs[field]) errs[field] = issue.message;
      }
    }
    if (!editingId.value && !form.value.api_key.trim())
      errs.api_key = t("providers.validation.apiKeyRequired");
    // endpoints 校验
    if (form.value.endpoints.length > 0) {
      const eps = form.value.endpoints;
      for (let i = 0; i < eps.length; i++) {
        if (!eps[i].base_url.trim()) {
          errs[`endpoint_${i}_base_url`] = t(
            "providers.validation.baseUrlRequired",
          );
        }
      }
      const types = eps.map((e) => e.api_type);
      if (new Set(types).size !== types.length) {
        errs.endpoints = t("providers.validation.duplicateApiType");
      }
    }
    if (concurrencyMode.value !== "none") {
      const mc = form.value.max_concurrency;
      if (!mc || mc < 1 || mc > MAX_CONCURRENCY)
        errs.max_concurrency = t("providers.validation.concurrencyRange", {
          min: 1,
          max: MAX_CONCURRENCY,
        });
      if (form.value.queue_timeout_ms < 0)
        errs.queue_timeout_ms = t("providers.validation.negativeNotAllowed");
      const qs = form.value.max_queue_size;
      if (!qs || qs < 1 || qs > MAX_QUEUE_SIZE)
        errs.max_queue_size = t("providers.validation.queueSizeRange", {
          min: 1,
          max: MAX_QUEUE_SIZE,
        });
    }
    errors.value = errs;
    return Object.keys(errs).length === 0;
  }

  function buildPayload(): ProviderFormPayload {
    const payload: ProviderFormPayload = {
      name: form.value.name,
      api_type: form.value.api_type,
      base_url: form.value.base_url,
      upstream_path: form.value.upstream_path || undefined,
      endpoints:
        form.value.endpoints.length > 0
          ? form.value.endpoints.map((ep) => ({
            api_type: ep.api_type,
            base_url: ep.base_url,
            upstream_path: ep.upstream_path || undefined,
            api_key: ep.api_key || undefined,
          }))
          : undefined,
      models: form.value.models.map((m) => ({
        name: m.name,
        context_window: m.context_window ?? undefined,
        patches: m.patches ?? undefined,
        stream_timeout_ms: m.stream_timeout_ms ?? undefined,
        capabilities: m.capabilities ?? undefined,
      })),
      is_active: form.value.is_active ? 1 : 0,
      max_concurrency:
        concurrencyMode.value === "none" ? 0 : form.value.max_concurrency,
      queue_timeout_ms:
        concurrencyMode.value === "none" ? 0 : form.value.queue_timeout_ms,
      max_queue_size:
        concurrencyMode.value === "none"
          ? DEFAULT_QUEUE_SIZE
          : form.value.max_queue_size,
      adaptive_enabled: concurrencyMode.value === "auto" ? 1 : 0,
      proxy_type: form.value.proxy_type || null,
      proxy_url: form.value.proxy_url?.trim() || null,
      proxy_username: form.value.proxy_username?.trim() || null,
      proxy_password: form.value.proxy_password || null,
    };
    if (form.value.api_key) payload.api_key = form.value.api_key;
    return payload;
  }

  function addModel() {
    const input = modelInput.value.trim();
    if (!input) return;
    const names = input
      .split(/[,，]/)
      .map((s) => s.trim())
      .filter(Boolean);
    for (const name of names) {
      if (!form.value.models.some((m) => m.name === name)) {
        form.value.models.push({
          name,
          context_window: modelContextWindow.value || DEFAULT_CONTEXT_WINDOW,
          patches: [],
          stream_timeout_ms: DEFAULT_STREAM_TIMEOUT_MS,
          capabilities: ["text"],
        });
      }
    }
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
  }

  function removeModel(index: number) {
    form.value.models.splice(index, 1);
  }

  function updateModel(index: number, updated: ModelConfig) {
    form.value.models[index].context_window = updated.contextWindow;
    form.value.models[index].patches = updated.patches;
  }

  /** 切换模型的指定能力。text 为基础能力，不可关闭。 */
  function toggleModelCapability(index: number, capability: string) {
    if (capability === "text") return;
    const model = form.value.models[index];
    const caps = model.capabilities ?? ["text"];
    const hasIt = caps.includes(capability);
    model.capabilities = hasIt
      ? caps.filter((c) => c !== capability)
      : [...caps, capability];
  }

  function updateModelTimeout(index: number, seconds: string | number) {
    const val = Number(seconds);
    form.value.models[index].stream_timeout_ms =
      val > 0 ? val * MS_PER_SECOND : null;
  }

  function onConcurrencyModeChange(mode: ConcurrencyMode) {
    concurrencyMode.value = mode;
    if (mode === "auto") {
      if (!form.value.max_concurrency || form.value.max_concurrency < 1)
        form.value.max_concurrency = DEFAULT_CONCURRENCY_AUTO;
      form.value.adaptive_enabled = true;
    } else if (mode === "manual") {
      if (!form.value.max_concurrency || form.value.max_concurrency < 1)
        form.value.max_concurrency = DEFAULT_CONCURRENCY;
      form.value.adaptive_enabled = false;
    }
  }

  function isOfficialOpenai(url: string): boolean {
    return url.includes("api.openai.com");
  }

  function openCreate() {
    editingId.value = null;
    form.value = { ...DEFAULT_FORM, models: [], endpoints: [] };
    concurrencyMode.value = "auto";
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
    presetHook.presetGroup.value = "";
    presetHook.presetPlan.value = "";
    errors.value = {};
    dialogOpen.value = true;
  }

  function openEdit(p: Provider) {
    editingId.value = p.id;
    const mc = p.max_concurrency ?? 0;
    if (mc === 0) concurrencyMode.value = "none";
    else if (p.adaptive_enabled) concurrencyMode.value = "auto";
    else concurrencyMode.value = "manual";
    form.value = {
      name: p.name,
      api_type: p.api_type,
      base_url: p.base_url,
      upstream_path: p.upstream_path || "",
      api_key: "",
      endpoints: (p.endpoints ?? []).map((ep) => ({
        api_type: ep.api_type,
        base_url: ep.base_url,
        upstream_path: ep.upstream_path ?? null,
        api_key: ep.api_key ?? null,
      })),
      models: (p.models || []).map((m) => ({
        name: m.name,
        context_window: m.context_window ?? DEFAULT_CONTEXT_WINDOW,
        patches: m.patches ?? [],
        stream_timeout_ms: m.stream_timeout_ms ?? null,
        capabilities: m.capabilities ?? ["text"],
      })),
      is_active: !!p.is_active,
      max_concurrency:
        concurrencyMode.value === "none" ? DEFAULT_CONCURRENCY_AUTO : mc,
      queue_timeout_ms: p.queue_timeout_ms ?? DEFAULT_QUEUE_TIMEOUT_MS,
      max_queue_size: p.max_queue_size ?? DEFAULT_QUEUE_SIZE,
      adaptive_enabled: concurrencyMode.value === "auto",
      proxy_type: p.proxy_type || "",
      proxy_url: p.proxy_url || "",
      proxy_username: p.proxy_username || "",
      proxy_password: "",
    };
    presetHook.presetGroup.value = "";
    presetHook.presetPlan.value = "";
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
    errors.value = {};
    dialogOpen.value = true;
    loadTransformRules(p.id);
  }

  return {
    form,
    errors,
    concurrencyMode,
    dialogOpen,
    editingId,
    modelInput,
    modelContextWindow,
    contextWindowSelect,
    transformForm,
    presetHook,
    validate,
    buildPayload,
    addModel,
    removeModel,
    updateModel,
    updateModelTimeout,
    toggleModelCapability,
    onConcurrencyModeChange,
    isOfficialOpenai,
    openCreate,
    openEdit,
    saveTransformRules,
  };
}

