  base_url: Type.String({ minLength: 1 }),
  upstream_path: Type.Optional(Type.Union([Type.String({ minLength: 1 }), Type.Null()])),
  api_key: Type.Optional(Type.Union([Type.String({ minLength: 1 }), Type.Null()])),
});

