    Type.Object({ id: Type.String(), stream_timeout_ms: Type.Optional(Type.Number({ minimum: 0, maximum: 86_400_000 })) })
  ]))),
  is_active: Type.Optional(Type.Number()),
  max_concurrency: Type.Optional(Type.Integer({ minimum: 0 })),
