interface ProviderRoutesOptions {
  db: Database.Database;
  stateRegistry?: StateRegistry;
  tracker?: RequestTracker;
  adaptiveController?: AdaptiveController;
  proxyAgentFactory?: ProxyAgentFactory;
}

interface ProviderHandlerDeps {
  db: Database.Database;
  stateRegistry?: StateRegistry;
  tracker?: RequestTracker;
  adaptiveController?: AdaptiveController;
}

async function handleCreateProvider(
  body: Static<typeof CreateProviderSchema>,
  reply: FastifyReply,
  deps: ProviderHandlerDeps,
) {
  const { db, stateRegistry, tracker, adaptiveController } = deps;
  if (!PROVIDER_NAME_RE.test(body.name)) {
    return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.VALIDATION_FAILED, "Provider 名称仅允许英文大小写字母、数字、横线和下划线"));
  }
  const existing = db.prepare("SELECT id FROM providers WHERE name = ?").get(body.name) as { id: string } | undefined;
  if (existing) {
    return reply.code(HTTP_CONFLICT).send(apiError(API_CODE.CONFLICT_NAME, `Provider 名称 '${body.name}' 已存在`));
  }
  const encryptionKey = getSetting(db, "encryption_key")!;

  // ---- endpoints 解析 ----
  let legacyApiType: "openai" | "openai-responses" | "anthropic";
  let legacyBaseUrl: string;
  let legacyUpstreamPath: string | null;
  let legacyApiKeyPlain: string;
  let endpointsSerialized: string | null;

  if (body.endpoints && body.endpoints.length > 0) {
    const result = validateAndEncryptEndpoints(body.endpoints, encryptionKey);
    if (!result.ok) {
      return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.VALIDATION_FAILED, result.message));
    }
    endpointsSerialized = serializeEndpoints(result.processed);
    legacyApiType = body.endpoints[0].api_type;
    legacyBaseUrl = body.endpoints[0].base_url;
    legacyUpstreamPath = body.endpoints[0].upstream_path ?? null;
    legacyApiKeyPlain = body.endpoints[0].api_key ?? body.api_key ?? "";
    if (!legacyApiKeyPlain) {
      return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.VALIDATION_FAILED, "第一个 endpoint 需要提供 api_key 或使用旧 api_key 字段"));
    }
  } else {
    if (!body.api_type || !body.base_url || !body.api_key) {
      return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.VALIDATION_FAILED, "缺少 endpoints 时，api_type/base_url/api_key 为必填"));
    }
    if (!isValidHttpUrl(body.base_url)) {
      return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.VALIDATION_FAILED, "base_url 格式无效，必须是以 http:// 或 https:// 开头的合法 URL"));
    }
    legacyApiType = body.api_type;
    legacyBaseUrl = body.base_url;
    legacyUpstreamPath = body.upstream_path ?? null;
    legacyApiKeyPlain = body.api_key;
    endpointsSerialized = serializeEndpoints([{
      api_type: body.api_type,
      base_url: body.base_url,
      upstream_path: body.upstream_path ?? null,
      api_key: null,
    }]);
  }

  const encryptedKey = encrypt(legacyApiKeyPlain, encryptionKey);
  const { entries: normalizedModels, overrides: contextOverrides } = extractModelOverrides((body.models ?? []) as ModelInput[]);
  const isAdaptiveEnabled = body.adaptive_enabled ?? 0;

  const effectiveProxyType = body.proxy_url?.trim() ? body.proxy_type : null;
  const effectiveProxyUrl = body.proxy_url?.trim() || null;

  const encryptedProxyUsername = (effectiveProxyType && body.proxy_username) ? encrypt(body.proxy_username, encryptionKey) : null;
  const encryptedProxyPassword = (effectiveProxyType && body.proxy_password) ? encrypt(body.proxy_password, encryptionKey) : null;
  const id = createProvider(db, {
    name: body.name,
    api_type: legacyApiType,
    base_url: legacyBaseUrl,
    upstream_path: legacyUpstreamPath,
    api_key: encryptedKey,
    api_key_preview: legacyApiKeyPlain.length > API_KEY_PREVIEW_MIN_LENGTH ? `${legacyApiKeyPlain.slice(0, API_KEY_PREVIEW_PREFIX_LEN)}...${legacyApiKeyPlain.slice(-API_KEY_PREVIEW_PREFIX_LEN)}` : "****",
    models: JSON.stringify(normalizedModels),
    is_active: body.is_active ?? 1,
    max_concurrency: body.max_concurrency ?? PROVIDER_CONCURRENCY_DEFAULTS.max_concurrency,
    queue_timeout_ms: body.queue_timeout_ms ?? PROVIDER_CONCURRENCY_DEFAULTS.queue_timeout_ms,
    max_queue_size: body.max_queue_size ?? PROVIDER_CONCURRENCY_DEFAULTS.max_queue_size,
    adaptive_enabled: isAdaptiveEnabled,
    proxy_type: effectiveProxyType,
    proxy_url: effectiveProxyUrl,
    proxy_username: encryptedProxyUsername,
    proxy_password: encryptedProxyPassword,
    endpoints: endpointsSerialized,
  });
  if (contextOverrides.length > 0) {
    setModelInfoForProvider(db, id, contextOverrides.map(o => ({ model_name: o.name, context_window: o.context_window })));
  }
  if (!isAdaptiveEnabled) {
    stateRegistry?.updateProviderConcurrency(id, {
      maxConcurrency: body.max_concurrency ?? PROVIDER_CONCURRENCY_DEFAULTS.max_concurrency,
      queueTimeoutMs: body.queue_timeout_ms ?? PROVIDER_CONCURRENCY_DEFAULTS.queue_timeout_ms,
      maxQueueSize: body.max_queue_size ?? PROVIDER_CONCURRENCY_DEFAULTS.max_queue_size,
    });
  }
  adaptiveController?.syncProvider(id, {
    adaptive_enabled: isAdaptiveEnabled,
    max_concurrency: body.max_concurrency ?? PROVIDER_CONCURRENCY_DEFAULTS.max_concurrency,
    queue_timeout_ms: body.queue_timeout_ms ?? PROVIDER_CONCURRENCY_DEFAULTS.queue_timeout_ms,
    max_queue_size: body.max_queue_size ?? PROVIDER_CONCURRENCY_DEFAULTS.max_queue_size,
  });
  tracker?.updateProviderConfig(id, {
    name: body.name,
    maxConcurrency: body.max_concurrency ?? PROVIDER_CONCURRENCY_DEFAULTS.max_concurrency,
    queueTimeoutMs: body.queue_timeout_ms ?? PROVIDER_CONCURRENCY_DEFAULTS.queue_timeout_ms,
    maxQueueSize: body.max_queue_size ?? PROVIDER_CONCURRENCY_DEFAULTS.max_queue_size,
  });
  return reply.code(HTTP_CREATED).send({ id });
}

export const adminProviderRoutes: FastifyPluginCallback<ProviderRoutesOptions> = (app, options, done) => {
  const { db, stateRegistry, tracker, adaptiveController, proxyAgentFactory } = options;

  app.get("/admin/api/providers", async (_request, reply) => {
    const encryptionKey = getSetting(db, "encryption_key")!;
    const providers = getAllProviders(db);
    return reply.send(providers.map((s) => {
      const modelEntries = parseModels(s.models || "[]");
      const overrides = new Map(
        getModelInfoForProvider(db, s.id).map(m => [m.model_name, m.context_window]),
      );
      return {
        id: s.id,
        name: s.name,
        api_type: s.api_type,
        base_url: s.base_url,
        upstream_path: s.upstream_path,
        api_key: s.api_key ? decrypt(s.api_key, encryptionKey) : "",
        models: buildModelInfoList(modelEntries, overrides),
        is_active: s.is_active,
        max_concurrency: s.max_concurrency,
        queue_timeout_ms: s.queue_timeout_ms,
        max_queue_size: s.max_queue_size,
        adaptive_enabled: s.adaptive_enabled,
        proxy_type: s.proxy_type,
        proxy_url: s.proxy_url,
        proxy_username: s.proxy_username ? decrypt(s.proxy_username, encryptionKey) : null,
        proxy_password: s.proxy_password ? decrypt(s.proxy_password, encryptionKey) : null,
        endpoints: parseEndpoints(s.endpoints).map(ep => ({
          api_type: ep.api_type,
          base_url: ep.base_url,
          upstream_path: ep.upstream_path ?? null,
          api_key: ep.api_key ? decrypt(ep.api_key, encryptionKey) : "",
        })),
        concurrency_status: stateRegistry?.getProviderStatus(s.id) ?? { active: 0, queued: 0 },
        created_at: s.created_at,
        updated_at: s.updated_at,
      };
    }));
  });

  app.post("/admin/api/providers", { schema: { body: CreateProviderSchema } }, async (request, reply) => {
    return handleCreateProvider(request.body as Static<typeof CreateProviderSchema>, reply, { db, stateRegistry, tracker, adaptiveController });
  });

  app.put("/admin/api/providers/:id", { schema: { body: UpdateProviderSchema } }, async (request, reply) => {
    const { id } = request.params as { id: string };
    const existing = getProviderById(db, id);
    if (!existing) {
      return reply.code(HTTP_NOT_FOUND).send(apiError(API_CODE.NOT_FOUND, "Provider not found"));
    }
    const body = request.body as Static<typeof UpdateProviderSchema>;
    if (body.name !== undefined && !PROVIDER_NAME_RE.test(body.name)) {
      return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.VALIDATION_FAILED, "Provider 名称仅允许英文大小写字母、数字、横线和下划线"));
    }
    const fields: Partial<Pick<Provider, 'name' | 'api_type' | 'base_url' | 'upstream_path' | 'api_key' | 'api_key_preview' | 'models' | 'is_active' | 'max_concurrency' | 'queue_timeout_ms' | 'max_queue_size' | 'adaptive_enabled' | 'proxy_type' | 'proxy_url' | 'proxy_username' | 'proxy_password' | 'endpoints'>> = {};
    if (body.name !== undefined) fields.name = body.name;
    if (body.api_type !== undefined) fields.api_type = body.api_type;
    if (body.base_url !== undefined) {
      if (!isValidHttpUrl(body.base_url)) {
        return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.VALIDATION_FAILED, "base_url 格式无效，必须是以 http:// 或 https:// 开头的合法 URL"));
      }
      fields.base_url = body.base_url;
    }
    if (body.upstream_path !== undefined) fields.upstream_path = body.upstream_path || null;
    if (body.is_active !== undefined) fields.is_active = body.is_active;
    if (body.models !== undefined) {
      const { entries, overrides } = extractModelOverrides(body.models as ModelInput[]);
      fields.models = JSON.stringify(entries);
      if (overrides.length > 0) {
        setModelInfoForProvider(db, id, overrides.map(o => ({ model_name: o.name, context_window: o.context_window })));
      } else {
        deleteAllModelInfoForProvider(db, id);
      }
    }
    if (body.max_concurrency !== undefined) fields.max_concurrency = body.max_concurrency;
    if (body.queue_timeout_ms !== undefined) fields.queue_timeout_ms = body.queue_timeout_ms;
    if (body.max_queue_size !== undefined) fields.max_queue_size = body.max_queue_size;
    if (body.adaptive_enabled !== undefined) fields.adaptive_enabled = body.adaptive_enabled;
    if (body.api_key) {
      fields.api_key = encrypt(body.api_key, getSetting(db, "encryption_key")!);
      fields.api_key_preview = body.api_key.length > API_KEY_PREVIEW_MIN_LENGTH ? `${body.api_key.slice(0, API_KEY_PREVIEW_PREFIX_LEN)}...${body.api_key.slice(-API_KEY_PREVIEW_PREFIX_LEN)}` : "****";
    }
    // Proxy field handling - 空URL视为不使用代理
    const effectiveProxyUrl = body.proxy_url !== undefined ? (body.proxy_url?.trim() || null) : undefined;
    const effectiveProxyType = effectiveProxyUrl !== undefined ? (effectiveProxyUrl ? body.proxy_type : null) : undefined;

    if (effectiveProxyType !== undefined) {
      fields.proxy_type = effectiveProxyType;
      fields.proxy_url = effectiveProxyUrl;
      if (!effectiveProxyType) {
        fields.proxy_username = null;
        fields.proxy_password = null;
      }
    }
    if (body.proxy_username !== undefined && effectiveProxyType) {
      fields.proxy_username = body.proxy_username ? encrypt(body.proxy_username, getSetting(db, "encryption_key")!) : null;
    }
    if (body.proxy_password !== undefined && effectiveProxyType) {
      fields.proxy_password = body.proxy_password ? encrypt(body.proxy_password, getSetting(db, "encryption_key")!) : null;
    }
    // ---- endpoints 处理 ----
    if (body.endpoints) {
      const ek = getSetting(db, "encryption_key")!;
      const result = validateAndEncryptEndpoints(body.endpoints, ek);
      if (!result.ok) {
        return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.VALIDATION_FAILED, result.message));
      }
      fields.endpoints = serializeEndpoints(result.processed);
      // 同步旧字段 = endpoints[0]
      fields.api_type = body.endpoints[0].api_type;
      fields.base_url = body.endpoints[0].base_url;
      fields.upstream_path = body.endpoints[0].upstream_path ?? null;
      const primaryApiKey = body.endpoints[0].api_key;
      if (primaryApiKey) {
        fields.api_key = encrypt(primaryApiKey, ek);
        fields.api_key_preview = primaryApiKey.length > API_KEY_PREVIEW_MIN_LENGTH ? `${primaryApiKey.slice(0, API_KEY_PREVIEW_PREFIX_LEN)}...${primaryApiKey.slice(-API_KEY_PREVIEW_PREFIX_LEN)}` : "****";
      }
    }
    updateProvider(db, id, fields);
    proxyAgentFactory?.invalidate(id);
    const updated = getProviderById(db, id)!;

    let cascade: CascadeResult | undefined;
    if (existing.is_active === 1 && body.is_active === 0) {
      cascade = cascadeProviderDisable(db, id);
      // 禁用时清理信号量和自适应并发，避免排队请求悬挂
      stateRegistry?.removeProvider(id);
      adaptiveController?.remove(id);
    }

    // 重新启用时重建信号量和自适应并发
    const concurrencyChanged = body.max_concurrency !== undefined || body.queue_timeout_ms !== undefined || body.max_queue_size !== undefined;
    const adaptiveChanged = body.adaptive_enabled !== undefined;
    const reenabled = existing.is_active === 0 && body.is_active === 1;
    const needsSync = concurrencyChanged || adaptiveChanged || reenabled;

    if (needsSync) {
      // adaptive 同步：syncProvider 内部根据 adaptive_enabled 决定是 init+syncToSemaphore 还是 remove+updateConfig
      adaptiveController?.syncProvider(id, {
        adaptive_enabled: updated.adaptive_enabled,
        max_concurrency: updated.max_concurrency,
        queue_timeout_ms: updated.queue_timeout_ms,
        max_queue_size: updated.max_queue_size,
      });
      // 非 adaptive 模式下手动同步信号量（adaptive 启用时由 syncProvider 内部管理）
      if (!updated.adaptive_enabled) {
        stateRegistry?.updateProviderConcurrency(id, {
          maxConcurrency: updated.max_concurrency,
          queueTimeoutMs: updated.queue_timeout_ms,
          maxQueueSize: updated.max_queue_size,
        });
      }
    }
    tracker?.updateProviderConfig(id, {
      name: body.name ?? existing.name,
      maxConcurrency: updated.max_concurrency,
      queueTimeoutMs: updated.queue_timeout_ms,
      maxQueueSize: updated.max_queue_size,
    });
    return reply.send({ success: true, cascadedGroups: cascade?.updatedGroups ?? [] });
  });

  app.get("/admin/api/providers/:id/dependencies", async (request, reply) => {
    const { id } = request.params as { id: string };
    const existing = getProviderById(db, id);
    if (!existing) {
      return reply.code(HTTP_NOT_FOUND).send(apiError(API_CODE.NOT_FOUND, "Provider not found"));
    }

    const references: string[] = [];

    const groups = getAllMappingGroups(db);
    for (const g of groups) {
      if (!g.is_active) continue;
      const refs: string[] = [];
      try {
        const rule = JSON.parse(g.rule);
        if (Array.isArray(rule.targets)) {
          for (let i = 0; i < rule.targets.length; i++) {
            const t = rule.targets[i];
            if (t.provider_id === id) {
              refs.push(`目标 ${i + 1} (${t.backend_model})`);
            }
            if (t.overflow_provider_id === id) {
              refs.push(`目标 ${i + 1} 溢出 (${t.overflow_model || "-"})`);
            }
          }
        }
      } catch { continue }
      for (const ref of refs) {
        references.push(`映射分组「${g.client_model}」: ${ref}`);
      }
    }

    return reply.send({ references });
  });

  app.delete("/admin/api/providers/:id", async (request, reply) => {
    const { id } = request.params as { id: string };
    const existing = getProviderById(db, id);
    if (!existing) {
      return reply.code(HTTP_NOT_FOUND).send(apiError(API_CODE.NOT_FOUND, "Provider not found"));
    }
    const groups = getAllMappingGroups(db);
    for (const g of groups) {
      try {
        const rule = JSON.parse(g.rule);
        const targets = Array.isArray(rule.targets) ? rule.targets : [];
        if (targets.some((t: Record<string, unknown>) => t?.provider_id === id)) {
          return reply.code(HTTP_CONFLICT).send(apiError(API_CODE.CONFLICT_REFERENCED, `Provider is referenced by mapping group '${g.client_model}'`));
        }
      } catch { continue }
    }
    proxyAgentFactory?.invalidate(id);
    deleteProvider(db, id);
    stateRegistry?.removeProvider(id);
    adaptiveController?.remove(id);
    tracker?.removeProviderConfig(id);
    return reply.send({ success: true });
  });

  // --- 从上游 Provider 获取可用模型列表 ---
  const FetchModelsSchema = Type.Object({
    base_url: Type.String({ minLength: 1 }),
    models_endpoint: Type.String({ minLength: 1 }),
    api_key: Type.String({ minLength: 1 }),
    api_type: Type.Union([Type.Literal("openai"), Type.Literal("anthropic")]),
  });

  app.post("/admin/api/providers/fetch-models", { schema: { body: FetchModelsSchema } }, async (request, reply) => {
    const { base_url, models_endpoint, api_key, api_type } = request.body as Static<typeof FetchModelsSchema>;

    const backend = { base_url };
    const clientHeaders: Record<string, string> = {};
    try {
      const result = await callGet(
        backend,
        api_key,
        clientHeaders as RawHeaders,
        models_endpoint,
        (cliHdrs, key) => buildUpstreamHeaders(cliHdrs, key, undefined, api_type),
      );

      if (result.statusCode !== HTTP_OK) {
        return reply.code(HTTP_BAD_REQUEST).send(apiError(
          API_CODE.BAD_REQUEST,
          `上游返回 HTTP ${result.statusCode}: ${result.body.substring(0, FETCH_MODELS_BODY_PREVIEW_LENGTH) as string}`,
        ));
      }

      let parsed: unknown;
      try {
        parsed = JSON.parse(result.body);
      } catch {
        return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.BAD_REQUEST, "上游返回非 JSON 响应"));
      }

      // OpenAI 格式: { object: "list", data: [{ id: "model-name", ... }] }
      // Anthropic 格式: { data: [{ type: "model", id: "model-name", ... }] }
      const data = (parsed as Record<string, unknown>)?.data;
      if (!Array.isArray(data)) {
        return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.BAD_REQUEST, "上游返回的模型列表格式不符合预期"));
      }

      const modelIds = data
        .map((item: unknown) => {
          if (typeof item === "string") return item;
          if (typeof item === "object" && item !== null && "id" in item) return (item as { id: string }).id;
          return null;
        })
        .filter((id): id is string => typeof id === "string")
        .sort();

      return reply.send(modelIds);
    } catch (err) {
      const message = err instanceof Error ? err.message : err instanceof Error ? err.message : JSON.stringify(err);
      return reply.code(HTTP_BAD_REQUEST).send(apiError(API_CODE.BAD_REQUEST, `连接上游失败: ${message}`));
    }
  });

  app.get("/admin/api/providers/:id/adaptive-status", async (request, reply) => {
    const { id } = request.params as { id: string };
    const status = adaptiveController?.getStatus(id);
    if (!status) return reply.code(HTTP_NOT_FOUND).send({ error: "Not found or adaptive not enabled" });
    return status;
  });

  done();
};

/**
 * Failover 循环 — 从 executeFailoverLoop() 提取。
 *
 * 每次迭代：
 * 1. 通过 ProxyPipeline 执行完整的 route → transform → transport 流程
 * 2. 处理 ProviderSwitchNeeded / SemaphoreQueueFullError / SemaphoreTimeoutError
 * 3. 管理 excludeTargets 跨迭代累积
 *
 * 与旧版区别：
 * - 使用 PipelineContext 代替 FailoverContext
 * - 使用 ProxyPipeline.execute() 代替手动编排各步骤
 * - 内置 hook 负责日志/溢出/patches 等，此文件只关注 failover 循环控制
 */
import { randomUUID } from "crypto";
import type { FastifyReply } from "fastify";
import { ProviderSwitchNeeded } from "../../core/errors.js";
import { SemaphoreQueueFullError, SemaphoreTimeoutError } from "../../core/errors.js";
import { getProviderById, updateLogClientStatus, insertRequestLog, updateLogStreamContent } from "../../db/index.js";
import { logUpstreamError, extractErrorInfo } from "../../db/upstream-error-logs.js";
import { getSetting } from "../../db/settings.js";
import { resolveMapping, filterExcluded } from "../routing/mapping-resolver.js";
import { resolveEndpoint } from "../routing/resolve-endpoint.js";
import { expandOverflowTargets } from "../routing/overflow.js";
import { computeModalityRedirectTargets } from "../routing/modality-redirect.js";
import { getConfig } from "../../config/index.js";
import type { ProxyErrorFormatter } from "../proxy-core.js";
import type { FormatAdapter } from "../format/types.js";
import type { FormatRegistry } from "../format/registry.js";
import { insertRejectedLog } from "../log-helpers.js";
import { logResilienceResult, collectTransportMetrics, sanitizeHeadersForLog } from "../proxy-logging.js";
import { buildUpstreamHeaders, buildUpstreamUrl } from "../proxy-core.js";
import { getModelStreamTimeout } from "../../db/providers.js";
import { buildTransportFn } from "../transport/transport-fn.js";
import { parseModels } from "../../config/model-context.js";
import { applyProviderPatches } from "../patch/index.js";
import { loadEnhancementConfig } from "../routing/enhancement-config.js";
import { extractFailedToolResults, getTransportStatusCode, serializeBlocksForStorage } from "./proxy-handler-utils.js";
import type { FailedToolResult } from "./proxy-handler-utils.js";
import { logToolErrors } from "../tool-error-logger.js";
import type { Target, MappingReason } from "../../core/types.js";
import type { RawHeaders } from "../types.js";
import type { PipelineContext } from "../pipeline/types.js";
import { PipelineAbort } from "../pipeline/types.js";
import { PipelineSnapshot } from "../pipeline-snapshot.js";
import type { ServiceContainer } from "../../core/container.js";
import { SERVICE_KEYS } from "../../core/container.js";
import type { RetryRuleMatcher } from "../orchestration/retry-rules.js";
import type { ProxyOrchestrator } from "../orchestration/orchestrator.js";
import type { RequestTracker } from "../../core/monitor/index.js";
import type { UsageWindowTracker } from "../routing/usage-window-tracker.js";
import type { ProxyAgentFactory } from "../transport/proxy-agent.js";
import type { PluginRegistry } from "../transform/plugin-registry.js";
import type { ResponseTransformContext } from "../transform/plugin-types.js";
import type { ApiType } from "../transform/types.js";
import Database from "better-sqlite3";

const HTTP_ERROR_THRESHOLD = 400;
const UPSTREAM_ERROR_STATUS = 502;
const HTTP_SERVICE_UNAVAILABLE = 503;
const MAX_FAILOVER_ITERATIONS = 10;

// ---------- Dependencies ----------

export interface FailoverLoopDeps {
  db: Database.Database;
  container: ServiceContainer;
  orchestrator: ProxyOrchestrator;
  proxyAgentFactory?: ProxyAgentFactory;
}

// ---------- Rejected log helper ----------

interface RejectParams {
  db: Database.Database;
  logId: string;
  apiType: string;
  model: string;
  startTime: number;
  isStream: boolean;
  routerKeyId: string | null;
  originalBody: Record<string, unknown>;
  clientHeaders: RawHeaders;
  isFailover: boolean;
  originalRequestId: string | null;
  sessionId: string | undefined;
  pipelineSnapshot?: string;
  matcher?: RetryRuleMatcher;
  logFileWriter?: import("../../storage/log-file-writer.js").LogFileWriter | null;
  mappingReason?: string | null;
}

// --- Plugin 调整 body 和 headers ---
function applyPluginAdjustments(
  pluginRegistry: import("../transform/plugin-registry.js").PluginRegistry | undefined,
  body: Record<string, unknown>,
  clientApiType: string,
  provider: { id: string; name: string; base_url: string; api_type: string },
): { headers: Record<string, string> } {
  if (!pluginRegistry) return { headers: {} };
  const pluginCtx: import("../transform/plugin-types.js").RequestTransformContext = {
    body,
    headers: {},
    sourceApiType: clientApiType as ApiType,
    targetApiType: provider.api_type as ApiType,
    provider: { id: provider.id, name: provider.name, base_url: provider.base_url, api_type: provider.api_type },
  };
  pluginRegistry.applyBeforeRequest(pluginCtx);
  pluginRegistry.applyAfterRequest(pluginCtx);
  return { headers: pluginCtx.headers };
}

function rejectAndReply(
  reply: FastifyReply,
  params: RejectParams,
  error: { statusCode: number; body: unknown },
  errorMessage: string,
  providerId?: string,
  afterLog?: () => void,
): FastifyReply {
  insertRejectedLog({
    db: params.db, logId: params.logId, apiType: params.apiType as "openai" | "openai-responses" | "anthropic", model: params.model,
    statusCode: error.statusCode, errorMessage, startTime: params.startTime,
    isStream: params.isStream, routerKeyId: params.routerKeyId,
    originalBody: params.originalBody, clientHeaders: params.clientHeaders,
    providerId: providerId ?? null, originalModel: null,
    isFailover: params.isFailover, originalRequestId: params.originalRequestId,
    sessionId: params.sessionId, pipelineSnapshot: params.pipelineSnapshot,
    matcher: params.matcher, logFileWriter: params.logFileWriter,
    mapping_reason: params.mappingReason ?? null,
  });
  try { afterLog?.(); } catch { /* tool error log 写入失败不影响响应 */ } // eslint-disable-line taste/no-silent-catch
  return reply.code(error.statusCode).send(error.body);
}

// ---------- Main failover loop ----------

/**
 * 执行 failover 循环。每次迭代通过 pipeline 处理请求，
 * 失败时将 target 加入 excludeTargets 并继续。
 */
// eslint-disable-next-line max-lines-per-function
export async function executeFailoverLoop(
  ctx: PipelineContext,
  errors: ProxyErrorFormatter,
  deps: FailoverLoopDeps,
  upstreamPath: string,
  adapter: FormatAdapter,
): Promise<FastifyReply> {
  const { request, reply } = ctx;
  const { db, container, orchestrator } = deps;
  const tracker = container.resolve<RequestTracker>(SERVICE_KEYS.tracker);
  const usageWindowTracker = container.resolve<UsageWindowTracker>(SERVICE_KEYS.usageWindowTracker);
  const formatRegistry = container.resolve<FormatRegistry>(SERVICE_KEYS.formatRegistry);
  const matcher = container.resolve<RetryRuleMatcher>(SERVICE_KEYS.matcher);
  const logFileWriter = container.resolve<import("../../storage/log-file-writer.js").LogFileWriter>(SERVICE_KEYS.logFileWriter);
  const pluginRegistry = container.resolve<PluginRegistry>(SERVICE_KEYS.pluginRegistry);
  const config = getConfig();
  const enhancementConfig = loadEnhancementConfig(db);

  const excludeTargets: Target[] = [];
  let rootLogId: string | null = null;
  let pendingToolErrors: FailedToolResult[] | null = null;

  const flushToolErrors = (providerId: string, model: string, reqLogId: string) => {
    if (!pendingToolErrors) return;
    logToolErrors(pendingToolErrors, {
      db, providerId, backendModel: model,
      clientAgentType: ctx.metadata.get("client_type") as string ?? "unknown",
      requestLogId: reqLogId,
      routerKeyId: request.routerKey?.id ?? null,
      sessionId: ctx.metadata.get("session_id") as string | undefined,
    });
    pendingToolErrors = null;
  };

  const clientModel = ctx.clientModel;
  const rawBody = ctx.rawBody;
  const clientApiType = ctx.apiType as "openai" | "openai-responses" | "anthropic";

  // BP-H4: 循环不变量预计算，避免每次迭代重复 JSON.stringify + sanitizeHeaders
  const cliHdrs: RawHeaders = request.headers as RawHeaders;
  const sanitizedClientHeaders = sanitizeHeadersForLog(cliHdrs as Record<string, string>);
  const precomputedClientReq = JSON.stringify({ headers: sanitizedClientHeaders, body: rawBody });

  // BP-H3: encryptionKey 用于 resolveEndpoint 解密
  const encryptionKey = getSetting(db, "encryption_key");

  // === 循环前：路由决策（resolveMapping → IR → OF 分层预计算） ===

  const precomputeSnapshot = new PipelineSnapshot();

  // 1. resolveMapping — 只调一次，不传 excludeTargets（exclude 在循环内处理）
  const resolveResult = resolveMapping(db, clientModel, { now: new Date() });

  // resolveMapping 返回 null 时，需要用占位 snapshot 做错误日志
  const rejectSnapshot = new PipelineSnapshot();

  /** 构建 RejectParams，消除 4 处重复构造 */
  const buildRejectCtx = (logId: string, snapshot: PipelineSnapshot, overrides?: Partial<RejectParams>): RejectParams => ({
    db, logId, apiType: ctx.apiType, model: clientModel,
    startTime: Date.now(),
    isStream: (ctx.body as Record<string, unknown>).stream === true,
    routerKeyId: request.routerKey?.id ?? null,
    originalBody: rawBody, clientHeaders: cliHdrs,
    isFailover: false, originalRequestId: null,
    sessionId: ctx.metadata.get("session_id") as string | undefined,
    pipelineSnapshot: snapshot.toJSON(),
    matcher, logFileWriter,
    ...overrides,
  });

  if (!resolveResult) {
    const logId = randomUUID();
    return rejectAndReply(reply, buildRejectCtx(logId, rejectSnapshot), errors.modelNotFound(clientModel), `No mapping found for model '${clientModel}'`);
  }

  let allTargets = resolveResult.allTargets ?? [resolveResult.target];
  const concurrencyOverride = resolveResult.concurrency_override;

  // 2. modality-redirect 层：模态重定向 → 可能 prepend fallback target
  allTargets = computeModalityRedirectTargets(db, allTargets, clientModel, ctx.body, precomputeSnapshot);

  // 2a. modality-redirect 层返回空列表 → 提前报错（无 target 支持请求模态）
  if (allTargets.length === 0) {
    return rejectAndReply(reply, buildRejectCtx(randomUUID(), precomputeSnapshot), errors.unsupportedModality(),
      `No eligible target: request modalities not supported by any available model`);
  }

  // 3. OF 层：为每个 target 预计算 overflow
  const targetsBeforeOF = allTargets.length;
  const ofResult = expandOverflowTargets(allTargets, db, ctx.body);
  allTargets = ofResult.targets;
  precomputeSnapshot.add({ stage: "overflow", triggered: allTargets.length > targetsBeforeOF });

  // 4. allowed_models 过滤：MRL fallback 和 overflow 扩展的 target 也必须受约束
  const allowedModels = request.routerKey?.allowed_models;
  let overflowIndices = ofResult.overflowIndices;
  if (allowedModels && allowedModels.length > 0) {
    // 重建 overflowIndices：filter 会改变 index，需同步更新
    const newOverflowIndices = new Set<number>();
    const filtered: Target[] = [];
    for (let i = 0; i < allTargets.length; i++) {
      if (allowedModels.includes(allTargets[i].backend_model)) {
        if (overflowIndices.has(i)) newOverflowIndices.add(filtered.length);
        filtered.push(allTargets[i]);
      }
    }
    allTargets = filtered;
    overflowIndices = newOverflowIndices;
    if (allTargets.length === 0) {
      return rejectAndReply(reply, buildRejectCtx(randomUUID(), precomputeSnapshot), errors.modelNotAllowed(clientModel),
        `No allowed model available for '${clientModel}'`);
    }
  }

  // 预计算完成，缓存到循环外
  const cachedTargets = allTargets;

  // 工具错误日志提取（循环外一次性执行）
  if (enhancementConfig.tool_error_logging_enabled) {
    const failures = extractFailedToolResults(ctx.body);
    if (failures.length > 0) {
      request.log.info({ failures: failures.length, sessionId: ctx.metadata.get("session_id") }, "Tool error results detected");
      pendingToolErrors = failures;
    }
  }

  // === while(true)：纯执行循环 ===
  let failoverIteration = 0;
  let lastFailoverTrigger: string | null = null;

  while (true) {
  // 请求被 kill 后 reply 已销毁，直接退出避免浪费 failover 迭代
    if (reply.raw.destroyed) return reply;
    if (++failoverIteration > MAX_FAILOVER_ITERATIONS) {
      return reply.code(HTTP_SERVICE_UNAVAILABLE).send({
        error: { message: `Max failover iterations (${MAX_FAILOVER_ITERATIONS}) exceeded`, type: "server_error", code: "failover_limit_exceeded" },
      });
    }
    const startTime = Date.now();
    const logId = randomUUID();
    if (rootLogId === null) rootLogId = logId;
    const isFailoverIteration = rootLogId !== logId;
    const routerKeyId = request.routerKey?.id ?? null;

    // 浅拷贝：后续操作只修改顶层属性（model），嵌套对象不被修改
    let currentBody = { ...ctx.body };
    const isStream = currentBody.stream === true;
    const iterationSnapshot = new PipelineSnapshot(precomputeSnapshot.getStages());

    const rCtx: RejectParams = buildRejectCtx(logId, iterationSnapshot, {
      startTime,
      isFailover: isFailoverIteration,
      originalRequestId: isFailoverIteration ? rootLogId : null,
    });

    // --- 选第一个非 excluded target ---
    const filtered = filterExcluded(cachedTargets, excludeTargets);
    if (filtered.length === 0) {
      return rejectAndReply(reply, rCtx, errors.upstreamConnectionFailed(),
        `All failover targets exhausted (${excludeTargets.length} attempted)`);
    }

    const resolved = filtered[0];
    const isFailover = cachedTargets.length > 1;

    // effectiveMappingReason: 首次迭代用 resolveResult.reason，溢出时覆盖
    let effectiveMappingReason: MappingReason = isFailoverIteration ? "failover_retry" : resolveResult.mappingReason;
    // 只有当前 target 是 overflow 扩展产生的才标记
    const resolvedIdx = cachedTargets.findIndex(t => t.provider_id === resolved.provider_id && t.backend_model === resolved.backend_model);
    if (overflowIndices.has(resolvedIdx)) effectiveMappingReason = "overflow_redirect";

    // 将 mappingReason 注入 rCtx，使后续 rejectAndReply 能写入诊断字段
    rCtx.mappingReason = effectiveMappingReason;

    const provider = getProviderById(db, resolved.provider_id);
    if (!provider || !provider.is_active) {
      lastFailoverTrigger = "provider_unavailable";
      insertRejectedLog({
        db, logId, apiType: clientApiType as "openai" | "openai-responses" | "anthropic",
        model: clientModel, statusCode: 503,
        errorMessage: `Provider '${resolved.provider_id}' unavailable`,
        startTime, isStream, routerKeyId,
        originalBody: rawBody, clientHeaders: cliHdrs,
        providerId: resolved.provider_id, originalModel: null,
        isFailover: isFailoverIteration, originalRequestId: isFailoverIteration ? rootLogId : null,
        sessionId: ctx.metadata.get("session_id") as string | undefined,
        pipelineSnapshot: iterationSnapshot.toJSON(),
        matcher, logFileWriter,
        mapping_reason: rCtx.mappingReason ?? null,
      });
      excludeTargets.push(resolved);
      continue;
    }

    // --- resolveEndpoint: 确定实际连接的 endpoint ---
    if (!encryptionKey) {
      return rejectAndReply(reply, rCtx, errors.providerUnavailable(),
        `Encryption key not configured`, provider.id,
        () => flushToolErrors(provider.id, resolved.backend_model ?? clientModel, logId));
    }
    const resolvedEndpoint = resolveEndpoint(provider, clientApiType, encryptionKey);

    // 当前迭代的工具错误刷新闭包（统一 6 处调用）
    const flushCurrentErrors = () => flushToolErrors(provider.id, resolved.backend_model ?? clientModel, logId);

    // --- 格式转换 + upstreamPath 决策 ---
    const resolvedPath = resolveUpstreamPath(formatRegistry, currentBody, ctx.apiType as ApiType, resolvedEndpoint.api_type as ApiType, resolvedEndpoint.upstream_path ?? undefined, upstreamPath, resolved.backend_model ?? clientModel ?? "");
    currentBody = resolvedPath.body;
    const effectiveApiType = resolvedPath.effectiveApiType;
    const effectiveUpstreamPath = resolvedPath.effectiveUpstreamPath;
    const needsTransform = resolvedPath.needsTransform;

    // --- routing ---
    currentBody = { ...currentBody, model: resolved.backend_model };
    iterationSnapshot.add({ stage: "routing", client_model: clientModel, backend_model: resolved.backend_model, provider_id: resolved.provider_id, strategy: cachedTargets.length > 1 ? "failover" : "scheduled", mapping_reason: effectiveMappingReason });

    // --- Plugin 调整 body 和 headers ---
    const pluginResult = applyPluginAdjustments(pluginRegistry, currentBody, clientApiType, { id: provider.id, name: provider.name, base_url: resolvedEndpoint.base_url, api_type: resolvedEndpoint.api_type });
    const injectedHeaders = pluginResult.headers;

    // --- Provider patches ---
    const providerModels = parseModels(provider.models || "[]");
    const { body: patchedBody, meta: patchMeta } = applyProviderPatches(currentBody, {
      base_url: resolvedEndpoint.base_url,
      api_type: resolvedEndpoint.api_type,
      models: providerModels,
    });
    iterationSnapshot.add({ stage: "provider_patch", types: patchMeta.types });

    // --- API key (resolvedEndpoint.api_key 已解密) ---
    const apiKey = resolvedEndpoint.api_key;

    // --- beforeSendProxy + Build logging data ---
    adapter.beforeSendProxy?.(patchedBody, isStream);
    const reqBodyStr = JSON.stringify(patchedBody);
    const clientReq = precomputedClientReq;
    const upstreamReqBase = JSON.stringify({
      url: buildUpstreamUrl(resolvedEndpoint.base_url, effectiveUpstreamPath),
      headers: sanitizeHeadersForLog(buildUpstreamHeaders(cliHdrs, apiKey, Buffer.byteLength(reqBodyStr), effectiveApiType)),
      body: reqBodyStr,
    });

    // --- Stream transforms ---
    // source=上游格式, target=客户端格式 — 流从上游流向客户端需要反向转换
    const formatTransform = needsTransform ? formatRegistry.createStreamTransform(resolvedEndpoint.api_type, ctx.apiType, resolved.backend_model) : undefined;
    if (formatTransform) {
      formatTransform.on("warning", (err) => request.log.warn({ err, logId }, "formatTransform warning"));
    }

    const responseTransform = needsTransform ? (bodyStr: string): string => {
      try {
        const parsed = JSON.parse(bodyStr) as Record<string, unknown>;
        if (parsed.type === "error" || parsed.error) {
          return formatRegistry.transformError(parsed, resolvedEndpoint.api_type, ctx.apiType);
        }
        let transformed = formatRegistry.transformResponse(parsed, resolvedEndpoint.api_type, ctx.apiType);
        if (pluginRegistry && !isStream) {
          try {
            const respCtx: ResponseTransformContext = {
              response: transformed,
              sourceApiType: resolvedEndpoint.api_type as "openai" | "openai-responses" | "anthropic",
              targetApiType: clientApiType,
              provider: { id: provider.id, name: provider.name, base_url: resolvedEndpoint.base_url, api_type: resolvedEndpoint.api_type },
            };
            pluginRegistry.applyBeforeResponse(respCtx);
            pluginRegistry.applyAfterResponse(respCtx);
            transformed = respCtx.response;
          } catch { /* response hooks best-effort */ } // eslint-disable-line taste/no-silent-catch
        }
        return JSON.stringify(transformed);
      } catch (err) {
        request.log.error({ err }, "responseTransform failed");
        return bodyStr;
      }
    } : undefined;

    // --- Build transport function ---
    const streamLoopEnabled = enhancementConfig.stream_loop_enabled;
    const transportFn = buildTransportFn({
      provider, apiKey, body: patchedBody, cliHdrs, reply, upstreamPath: effectiveUpstreamPath, apiType: effectiveApiType,
      isStream, startTime, logId, effectiveModel: clientModel,
      streamTimeoutMs: getModelStreamTimeout(provider, resolved.backend_model),
      tracker, matcher, request,
      streamLoopEnabled, formatTransform, responseTransform, injectedHeaders,
      timeoutContext: { modelId: resolved.backend_model, providerId: provider.id },
      proxyAgentFactory: deps.proxyAgentFactory,
      resolvedBaseUrl: resolvedEndpoint.base_url,
    });

    const pipelineSnapshot = iterationSnapshot.toJSON();

    // --- Execute through orchestrator ---
    try {
      const resilienceResult = await orchestrator.handle(
        request, reply, clientApiType,
        { resolved, provider, clientModel, isStream, trackerId: logId, sessionId: ctx.metadata.get("session_id") as string | undefined, clientRequest: clientReq, upstreamRequest: upstreamReqBase, concurrencyOverride, mappingReason: effectiveMappingReason },
        { retryBaseDelayMs: config.RETRY_BASE_DELAY_MS, isFailover, ruleMatcher: matcher, transportFn },
      );

      // 日志记录
      const lastLogId = logResilienceResult(
        db,
        {
          apiType: clientApiType,
          model: clientModel, providerId: provider.id, isStream,
          clientReq, upstreamReqBase, logId, routerKeyId, originalModel: null, sessionId: ctx.metadata.get("session_id") as string | undefined,
          failover: { isFailoverIteration, rootLogId: rootLogId! },
          pipelineSnapshot,
          matcher, logFileWriter,
          resilienceAction: resilienceResult.finalDecision?.action,
          resilienceReason: resilienceResult.finalDecision?.action === "abort"
            ? (resilienceResult.finalDecision as { action: "abort"; reason: string }).reason
            : null,
          mappingReason: effectiveMappingReason,
          failoverTrigger: lastFailoverTrigger,
          upstreamApiType: resolvedEndpoint.api_type,
          upstreamBaseUrl: resolvedEndpoint.base_url,
        },
        resilienceResult.attempts, resilienceResult.result, startTime,
      );
      collectTransportMetrics(db, clientApiType, resilienceResult.result, isStream, lastLogId, provider.id, resolved.backend_model, request, routerKeyId, getTransportStatusCode(resilienceResult.result), ctx.metadata.get("client_type") as string | undefined, ctx.metadata.get("session_id") as string | undefined, tracker, ctx.metadata);

      // flush tool errors
      flushToolErrors(provider.id, resolved.backend_model ?? clientModel, lastLogId);

      // Stream timeout
      if (resilienceResult.result.kind === "stream_abort" && resilienceResult.result.timeoutContext) {
        const { modelId, providerId } = resilienceResult.result.timeoutContext;
        const msg = `Stream timeout: no data received for ${resilienceResult.result.timeoutMs}ms (model: ${modelId}, provider: ${providerId})`;
        const errBody = clientApiType === "anthropic"
          ? { type: "error", error: { type: "api_error", message: msg } }
          : { error: { message: msg, type: "server_error", code: "stream_timeout" } };
        try { reply.raw.write(`data: ${JSON.stringify(errBody)}\n\n`); } catch { /* client disconnected */ } // eslint-disable-line taste/no-silent-catch
        try { reply.raw.end(); } catch { /* client disconnected */ } // eslint-disable-line taste/no-silent-catch
      }

      const tr = resilienceResult.result;
      const succeeded = tr.kind === "success" || tr.kind === "stream_success" || tr.kind === "stream_abort";
      if (succeeded) usageWindowTracker?.recordRequest(provider.id, routerKeyId ?? undefined);

      // 失败时写入 upstream_error_logs
      if (!succeeded) {
        const body = 'body' in tr ? tr.body : '';
        const { errorType, errorMessage } = extractErrorInfo(body);
        const trStatusCode = getTransportStatusCode(tr);
        if (trStatusCode !== null) {
          logUpstreamError(db, {
            request_log_id: lastLogId,
            provider_id: provider.id,
            backend_model: resolved.backend_model ?? clientModel,
            status_code: trStatusCode,
            error_type: errorType,
            error_message: errorMessage,
            client_agent_type: ctx.metadata.get("client_type") as string ?? "unknown",
            router_key_id: routerKeyId,
            session_id: ctx.metadata.get("session_id") as string | null ?? null,
            retry_count: resilienceResult.attempts.length - 1,
          });
        }
      }

      // 流式内容日志
      if (isStream && tracker) {
        const sc = tracker.get(logId)?.streamContent;
        const blocks = sc?.blocks;
        const hasStructured = blocks && blocks.length > 0 && blocks.some((b: { type: string }) => b.type !== "text");
        const content = hasStructured
          ? serializeBlocksForStorage(blocks, clientApiType)
          : (sc?.textContent || "");
        if (content) {
          updateLogStreamContent(db, lastLogId, content);
        }
      }

      // Failover 场景：如果失败且 headers 未发送，继续下一个 target
      if (isFailover && !reply.raw.headersSent) {
        const failed = tr.kind === "throw"
          || ("statusCode" in tr && tr.statusCode >= HTTP_ERROR_THRESHOLD);
        if (failed) {
          lastFailoverTrigger = tr.kind === "throw" ? "throw" : `status_${("statusCode" in tr ? tr.statusCode : 0)}`;
          excludeTargets.push(resolved);
          continue;
        }
      }

      // 发送响应（orchestrator 对部分场景不发送）
      if (!reply.raw.headersSent) {
        if (tr.kind === "success") {
          return reply.code(tr.statusCode).send(tr.body);
        }
        if (tr.kind === "stream_error") {
          // stream_error + headersSent 已在 orchestrator.sendResponse 中处理
          // 此处为 !headersSent 分支：格式化错误体并发送
          const trStatus = getTransportStatusCode(tr);
          if (trStatus !== null) updateLogClientStatus(db, lastLogId, trStatus);
          const formattedBody = adapter.formatError(
            'body' in tr ? tr.body : "stream error",
          ) ?? { error: { message: "stream error", type: "server_error" } };
          reply.header("content-type", "application/json");
          return reply.code(tr.statusCode).send(formattedBody);
        }
        if (tr.kind === "throw" || (tr.kind === "error" && tr.statusCode >= HTTP_ERROR_THRESHOLD)) {
          const err = errors.upstreamConnectionFailed();
          updateLogClientStatus(db, lastLogId, err.statusCode);
          return reply.code(err.statusCode).send(err.body);
        }
        // 未知 TransportResult kind 的兜底响应
        return reply.code(UPSTREAM_ERROR_STATUS).send(
          adapter.formatError("Unhandled transport result") ?? { error: { message: "Unhandled transport result", type: "server_error" } },
        );
      }

      return reply;
    } catch (e: unknown) {
      if (e instanceof PipelineAbort) {
        return reply.code(e.statusCode).send(e.body);
      }

      if (e instanceof ProviderSwitchNeeded) {
        if (reply.raw.headersSent) return reply;
        // 补写失败日志
        if (e.attempts && e.attempts.length > 0) {
          const fakeResult = e.lastResult ?? { kind: "throw" as const, error: new Error("provider switch") };
          logResilienceResult(
            db,
            {
              apiType: clientApiType,
              model: clientModel, providerId: provider.id, isStream,
              clientReq, upstreamReqBase, logId, routerKeyId, originalModel: null, sessionId: ctx.metadata.get("session_id") as string | undefined,
              failover: { isFailoverIteration, rootLogId: rootLogId! },
              pipelineSnapshot,
              matcher, logFileWriter,
              resilienceAction: "failover",
              resilienceReason: "provider_switch_needed",
              mappingReason: effectiveMappingReason,
              failoverTrigger: e.constructor.name,
              upstreamApiType: resolvedEndpoint.api_type,
              upstreamBaseUrl: resolvedEndpoint.base_url,
            },
            e.attempts, fakeResult, startTime,
          );
        }
        flushCurrentErrors();
        lastFailoverTrigger = e.constructor.name;
        excludeTargets.push(resolved);
        continue;
      }

      if (e instanceof SemaphoreQueueFullError) {
        return rejectAndReply(reply, rCtx, errors.concurrencyQueueFull(provider.id),
          `Concurrency queue full for provider '${provider.id}'`, provider.id,
          flushCurrentErrors);
      }
      if (e instanceof SemaphoreTimeoutError) {
        return rejectAndReply(reply, rCtx, errors.concurrencyTimeout(provider.id, (e as SemaphoreTimeoutError).timeoutMs),
          `Concurrency wait timeout for provider '${provider.id}' (${(e as SemaphoreTimeoutError).timeoutMs}ms)`, provider.id,
          flushCurrentErrors);
      }

      // 请求被主动 kill（abort + reply destroy），直接退出不写日志
      if (e instanceof Error && e.name === "AbortError") {
        return reply;
      }

      // 其他未知错误
      const errMsg = e instanceof Error ? e.message : JSON.stringify(e);
      request.log.debug({ logId, error: errMsg, action: "upstream_error" });
      insertRequestLog(db, {
        id: logId, api_type: clientApiType,
        model: clientModel, provider_id: provider.id,
        status_code: UPSTREAM_ERROR_STATUS, latency_ms: Date.now() - startTime, is_stream: isStream ? 1 : 0,
        error_message: errMsg || "Upstream connection failed", created_at: new Date().toISOString(),
        client_request: clientReq, upstream_request: upstreamReqBase,
        is_failover: isFailoverIteration ? 1 : 0, original_request_id: isFailoverIteration ? rootLogId : null,
        router_key_id: routerKeyId, original_model: null,
        session_id: ctx.metadata.get("session_id") as string | undefined,
        pipeline_snapshot: pipelineSnapshot,
        transport_kind: "throw",
        mapping_reason: rCtx.mappingReason ?? null,
        upstream_api_type: resolvedEndpoint.api_type,
        upstream_base_url: resolvedEndpoint.base_url,
      }, (matcher || logFileWriter) ? {
        matcher, logFileWriter, responseBody: null,
      } : undefined);
      flushCurrentErrors();
      const err = errors.upstreamConnectionFailed();
      return reply.code(err.statusCode).send(err.body);
    }
  }
}

// --- 格式转换 + upstreamPath 决策 ---
function resolveUpstreamPath(
  formatRegistry: import("../format/registry.js").FormatRegistry,
  body: Record<string, unknown>,
  clientApiType: ApiType,
  providerApiType: ApiType,
  providerUpstreamPath: string | undefined,
  defaultUpstreamPath: string,
  backendModel: string,
): { body: Record<string, unknown>; effectiveApiType: ApiType; effectiveUpstreamPath: string; needsTransform: boolean } {
  const needsTransform = formatRegistry.needsTransform(clientApiType, providerApiType);
  let effectiveApiType: ApiType = clientApiType;
  let effectiveUpstreamPath = defaultUpstreamPath;

  if (needsTransform) {
    const transformed = formatRegistry.transformRequest(body, clientApiType, providerApiType, backendModel);
    body = transformed.body as Record<string, unknown>;
    effectiveUpstreamPath = transformed.upstreamPath;
    effectiveApiType = providerApiType;
  }

  if (providerUpstreamPath) {
    effectiveUpstreamPath = providerUpstreamPath;
  }

  return { body, effectiveApiType, effectiveUpstreamPath, needsTransform };
}

import { ref, computed } from "vue";
import { useI18n } from "vue-i18n";
import * as z from "zod";
import type { ProviderPayload } from "@/api/client";
import type { Provider, ModelInfo, ProviderEndpoint } from "@/types/mapping";
import { DEFAULT_CONTEXT_WINDOW, DEFAULT_STREAM_TIMEOUT_MS } from "@/constants";
import type { ModelConfig } from "@/components/quick-setup/types";
import { useTransformRules } from "@/composables/useTransformRules";
import { useProviderPresets } from "@/composables/useProviderPresets";
import type { ConcurrencyMode } from "@/types/concurrency";

const DEFAULT_CONCURRENCY = 3;
const DEFAULT_CONCURRENCY_AUTO = 10;
const DEFAULT_QUEUE_TIMEOUT_MS = 120_000;
const DEFAULT_QUEUE_SIZE = 10;
const MAX_CONCURRENCY = 100;
const MAX_QUEUE_SIZE = 1000;
const CONTEXT_K = 1000;
const CONTEXT_M = 1_000_000;
const MS_PER_SECOND = 1000;

interface FormState {
  name: string;
  api_type: string;
  base_url: string;
  upstream_path: string;
  api_key: string;
  endpoints: ProviderEndpoint[];
  models: ModelInfo[];
  is_active: boolean;
  max_concurrency: number;
  queue_timeout_ms: number;
  max_queue_size: number;
  adaptive_enabled: boolean;
  proxy_type: string;
  proxy_url: string;
  proxy_username: string;
  proxy_password: string;
}

const DEFAULT_FORM: FormState = {
  name: "",
  api_type: "anthropic",
  base_url: "",
  upstream_path: "",
  api_key: "",
  endpoints: [],
  models: [],
  is_active: true,
  max_concurrency: DEFAULT_CONCURRENCY_AUTO,
  queue_timeout_ms: DEFAULT_QUEUE_TIMEOUT_MS,
  max_queue_size: DEFAULT_QUEUE_SIZE,
  adaptive_enabled: true,
  proxy_type: "",
  proxy_url: "",
  proxy_username: "",
  proxy_password: "",
};

const CONTEXT_WINDOW_OPTIONS = [
  { label: "8K", value: "8000" },
  { label: "16K", value: "16000" },
  { label: "32K", value: "32000" },
  { label: "64K", value: "64000" },
  { label: "128K", value: "128000" },
  { label: "160K", value: "160000" },
  { label: "200K", value: "200000" },
  { label: "256K", value: "256000" },
  { label: "1M", value: "1000000" },
] as const;

export const API_TYPE_LABELS: Record<string, string> = {
  openai: "OpenAI Chat Completions",
  "openai-responses": "OpenAI Responses",
  anthropic: "Anthropic Messages",
};

export { CONTEXT_WINDOW_OPTIONS, MS_PER_SECOND, CONTEXT_K, CONTEXT_M };

type ProviderFormPayload = Pick<
  ProviderPayload,
  | "name"
  | "api_type"
  | "base_url"
  | "upstream_path"
  | "models"
  | "is_active"
  | "max_concurrency"
  | "queue_timeout_ms"
  | "max_queue_size"
  | "adaptive_enabled"
  | "proxy_type"
  | "proxy_url"
  | "proxy_username"
  | "proxy_password"
  | "endpoints"
> & { api_key?: string };

export function useProviderForm() {
  const { t } = useI18n();
  const { transformForm, loadTransformRules, saveTransformRules } =
    useTransformRules();

  const form = ref<FormState>({ ...DEFAULT_FORM });
  const errors = ref<Record<string, string>>({});
  const concurrencyMode = ref<ConcurrencyMode>("auto");
  const dialogOpen = ref(false);
  const editingId = ref<string | null>(null);
  const modelInput = ref("");
  const modelContextWindow = ref(DEFAULT_CONTEXT_WINDOW);
  const contextWindowSelect = computed({
    get: () => `${modelContextWindow.value}`,
    set: (val: string) => {
      modelContextWindow.value = Number(val);
    },
  });

  const presetHook = useProviderPresets(form);

  function validate(): boolean {
    const schema = z.object({
      name: z
        .string()
        .min(1, t("providers.validation.nameRequired"))
        .regex(/^[a-zA-Z0-9_-]+$/, t("providers.validation.namePattern")),
      base_url: z
        .string()
        .min(1, t("providers.validation.baseUrlRequired"))
        .url(t("providers.validation.baseUrlInvalid")),
    });
    const errs: Record<string, string> = {};
    const result = schema.safeParse({
      name: form.value.name.trim(),
      base_url: form.value.base_url.trim(),
    });
    if (!result.success) {
      for (const issue of result.error.issues) {
        const field = issue.path[0] as string;
        if (!errs[field]) errs[field] = issue.message;
      }
    }
    if (!editingId.value && !form.value.api_key.trim())
      errs.api_key = t("providers.validation.apiKeyRequired");
    // endpoints 校验
    if (form.value.endpoints.length > 0) {
      const eps = form.value.endpoints;
      for (let i = 0; i < eps.length; i++) {
        if (!eps[i].base_url.trim()) {
          errs[`endpoint_${i}_base_url`] = t(
            "providers.validation.baseUrlRequired",
          );
        }
      }
      const types = eps.map((e) => e.api_type);
      if (new Set(types).size !== types.length) {
        errs.endpoints = t("providers.validation.duplicateApiType");
      }
    }
    if (concurrencyMode.value !== "none") {
      const mc = form.value.max_concurrency;
      if (!mc || mc < 1 || mc > MAX_CONCURRENCY)
        errs.max_concurrency = t("providers.validation.concurrencyRange", {
          min: 1,
          max: MAX_CONCURRENCY,
        });
      if (form.value.queue_timeout_ms < 0)
        errs.queue_timeout_ms = t("providers.validation.negativeNotAllowed");
      const qs = form.value.max_queue_size;
      if (!qs || qs < 1 || qs > MAX_QUEUE_SIZE)
        errs.max_queue_size = t("providers.validation.queueSizeRange", {
          min: 1,
          max: MAX_QUEUE_SIZE,
        });
    }
    errors.value = errs;
    return Object.keys(errs).length === 0;
  }

  function buildPayload(): ProviderFormPayload {
    const payload: ProviderFormPayload = {
      name: form.value.name,
      api_type: form.value.api_type,
      base_url: form.value.base_url,
      upstream_path: form.value.upstream_path || undefined,
      endpoints:
        form.value.endpoints.length > 0
          ? form.value.endpoints.map((ep) => ({
            api_type: ep.api_type,
            base_url: ep.base_url,
            upstream_path: ep.upstream_path || undefined,
            api_key: ep.api_key || undefined,
          }))
          : undefined,
      models: form.value.models.map((m) => ({
        name: m.name,
        context_window: m.context_window ?? undefined,
        patches: m.patches ?? undefined,
        stream_timeout_ms: m.stream_timeout_ms ?? undefined,
        capabilities: m.capabilities ?? undefined,
      })),
      is_active: form.value.is_active ? 1 : 0,
      max_concurrency:
        concurrencyMode.value === "none" ? 0 : form.value.max_concurrency,
      queue_timeout_ms:
        concurrencyMode.value === "none" ? 0 : form.value.queue_timeout_ms,
      max_queue_size:
        concurrencyMode.value === "none"
          ? DEFAULT_QUEUE_SIZE
          : form.value.max_queue_size,
      adaptive_enabled: concurrencyMode.value === "auto" ? 1 : 0,
      proxy_type: form.value.proxy_type || null,
      proxy_url: form.value.proxy_url?.trim() || null,
      proxy_username: form.value.proxy_username?.trim() || null,
      proxy_password: form.value.proxy_password || null,
    };
    if (form.value.api_key) payload.api_key = form.value.api_key;
    return payload;
  }

  function addModel() {
    const input = modelInput.value.trim();
    if (!input) return;
    const names = input
      .split(/[,，]/)
      .map((s) => s.trim())
      .filter(Boolean);
    for (const name of names) {
      if (!form.value.models.some((m) => m.name === name)) {
        form.value.models.push({
          name,
          context_window: modelContextWindow.value || DEFAULT_CONTEXT_WINDOW,
          patches: [],
          stream_timeout_ms: DEFAULT_STREAM_TIMEOUT_MS,
          capabilities: ["text"],
        });
      }
    }
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
  }

  function removeModel(index: number) {
    form.value.models.splice(index, 1);
  }

  function updateModel(index: number, updated: ModelConfig) {
    form.value.models[index].context_window = updated.contextWindow;
    form.value.models[index].patches = updated.patches;
  }

  /** 切换模型的指定能力。text 为基础能力，不可关闭。 */
  function toggleModelCapability(index: number, capability: string) {
    if (capability === "text") return;
    const model = form.value.models[index];
    const caps = model.capabilities ?? ["text"];
    const hasIt = caps.includes(capability);
    model.capabilities = hasIt
      ? caps.filter((c) => c !== capability)
      : [...caps, capability];
  }

  function updateModelTimeout(index: number, seconds: string | number) {
    const val = Number(seconds);
    form.value.models[index].stream_timeout_ms =
      val > 0 ? val * MS_PER_SECOND : null;
  }

  function onConcurrencyModeChange(mode: ConcurrencyMode) {
    concurrencyMode.value = mode;
    if (mode === "auto") {
      if (!form.value.max_concurrency || form.value.max_concurrency < 1)
        form.value.max_concurrency = DEFAULT_CONCURRENCY_AUTO;
      form.value.adaptive_enabled = true;
    } else if (mode === "manual") {
      if (!form.value.max_concurrency || form.value.max_concurrency < 1)
        form.value.max_concurrency = DEFAULT_CONCURRENCY;
      form.value.adaptive_enabled = false;
    }
  }

  function isOfficialOpenai(url: string): boolean {
    return url.includes("api.openai.com");
  }

  function openCreate() {
    editingId.value = null;
    form.value = { ...DEFAULT_FORM, models: [], endpoints: [] };
    concurrencyMode.value = "auto";
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
    presetHook.presetGroup.value = "";
    presetHook.presetPlan.value = "";
    errors.value = {};
    dialogOpen.value = true;
  }

  function openEdit(p: Provider) {
    editingId.value = p.id;
    const mc = p.max_concurrency ?? 0;
    if (mc === 0) concurrencyMode.value = "none";
    else if (p.adaptive_enabled) concurrencyMode.value = "auto";
    else concurrencyMode.value = "manual";
    form.value = {
      name: p.name,
      api_type: p.api_type,
      base_url: p.base_url,
      upstream_path: p.upstream_path || "",
      api_key: "",
      endpoints: (p.endpoints ?? []).map((ep) => ({
        api_type: ep.api_type,
        base_url: ep.base_url,
        upstream_path: ep.upstream_path ?? null,
        api_key: ep.api_key ?? null,
      })),
      models: (p.models || []).map((m) => ({
        name: m.name,
        context_window: m.context_window ?? DEFAULT_CONTEXT_WINDOW,
        patches: m.patches ?? [],
        stream_timeout_ms: m.stream_timeout_ms ?? null,
        capabilities: m.capabilities ?? ["text"],
      })),
      is_active: !!p.is_active,
      max_concurrency:
        concurrencyMode.value === "none" ? DEFAULT_CONCURRENCY_AUTO : mc,
      queue_timeout_ms: p.queue_timeout_ms ?? DEFAULT_QUEUE_TIMEOUT_MS,
      max_queue_size: p.max_queue_size ?? DEFAULT_QUEUE_SIZE,
      adaptive_enabled: concurrencyMode.value === "auto",
      proxy_type: p.proxy_type || "",
      proxy_url: p.proxy_url || "",
      proxy_username: p.proxy_username || "",
      proxy_password: "",
    };
    presetHook.presetGroup.value = "";
    presetHook.presetPlan.value = "";
    modelInput.value = "";
    modelContextWindow.value = DEFAULT_CONTEXT_WINDOW;
    errors.value = {};
    dialogOpen.value = true;
    loadTransformRules(p.id);
  }

  return {
    form,
    errors,
    concurrencyMode,
    dialogOpen,
    editingId,
    modelInput,
    modelContextWindow,
    contextWindowSelect,
    transformForm,
    presetHook,
    validate,
    buildPayload,
    addModel,
    removeModel,
    updateModel,
    updateModelTimeout,
    toggleModelCapability,
    onConcurrencyModeChange,
    isOfficialOpenai,
    openCreate,
    openEdit,
    saveTransformRules,
  };
}

/**
 * Failover 循环 — 从 executeFailoverLoop() 提取。
 *
 * 每次迭代：
 * 1. 通过 ProxyPipeline 执行完整的 route → transform → transport 流程
 * 2. 处理 ProviderSwitchNeeded / SemaphoreQueueFullError / SemaphoreTimeoutError
 * 3. 管理 excludeTargets 跨迭代累积
 *
 * 与旧版区别：
 * - 使用 PipelineContext 代替 FailoverContext
 * - 使用 ProxyPipeline.execute() 代替手动编排各步骤
 * - 内置 hook 负责日志/溢出/patches 等，此文件只关注 failover 循环控制
 */
