const API_KEY_PREVIEW_MIN_LENGTH = 8;
const FETCH_MODELS_BODY_PREVIEW_LENGTH = 200;

interface CascadeResult {
  updatedGroups: Array<{ id: string; client_model: string; disabled: boolean }>;
}

function cascadeProviderDisable(db: Database.Database, providerId: string): CascadeResult {
  const result: CascadeResult = { updatedGroups: [] };
  const groups = getAllMappingGroups(db);

  for (const g of groups) {
    if (!g.is_active) continue;

    let rule: Record<string, unknown>;
    try {
      rule = JSON.parse(g.rule) as Record<string, unknown>;
    } catch { continue }

    let modified = false;
    let shouldDisable = false;

    // 归一化旧格式 { default, windows } → { targets }（向后兼容 migration 026 前数据）
    if (!Array.isArray(rule.targets)) {
      const legacyDefault = rule["default"];
      if (typeof legacyDefault === "object" && legacyDefault !== null) {
        rule.targets = [legacyDefault];
      }
    }

    const targets = rule.targets as Array<Record<string, string>> | undefined;
    if (Array.isArray(targets)) {
      const filtered = targets.filter((t) => {
        if (t.provider_id === providerId) {
          modified = true;
          return false;
        }
        if (t.overflow_provider_id === providerId) {
          delete t.overflow_provider_id;
          delete t.overflow_model;
          modified = true;
        }
        return true;
      });
      rule.targets = filtered;
      if (filtered.length === 0 && modified) {
        shouldDisable = true;
      }
    }

    if (modified) {
      const fields: { rule: string; is_active?: number } = { rule: JSON.stringify(rule) };
      if (shouldDisable) fields.is_active = 0;
      updateMappingGroup(db, g.id, fields);
      result.updatedGroups.push({ id: g.id, client_model: g.client_model, disabled: shouldDisable });
    }
  }

  return result;
}

type ModelInput = string | { name?: string; id?: string; context_window?: number; patches?: string[]; stream_timeout_ms?: number; capabilities?: string[] };

interface ModelOverride {
  name: string;
  context_window: number;
}

function extractModelOverrides(models: ModelInput[]): {
  entries: ModelEntry[];
  overrides: ModelOverride[];
} {
  const entries: ModelEntry[] = [];
  const overrides: ModelOverride[] = [];
  for (const m of models) {
    if (typeof m === "string") {
      entries.push({ name: m, patches: [] });
      continue;
    }
    const name = m.name ?? m.id;
    if (!name) continue;
    const entry: ModelEntry = { name, patches: (m.patches ?? []).map(normalizePatchName) };
    if (m.stream_timeout_ms != null) entry.stream_timeout_ms = m.stream_timeout_ms;
    if (m.capabilities != null && Array.isArray(m.capabilities)) entry.capabilities = m.capabilities;
    entries.push(entry);
    if (m.name != null && m.context_window != null) {
      overrides.push({ name: m.name, context_window: m.context_window });
    }
  }
  return { entries, overrides };
}
const API_KEY_PREVIEW_PREFIX_LEN = 4;
const PROVIDER_NAME_RE = /^[a-zA-Z0-9_-]+$/;

/** 校验 base_url 是否为合法的 HTTP(S) URL */
function isValidHttpUrl(str: string): boolean {
  try {
    const url = new URL(str);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
}

interface EndpointInput {
  api_type: "openai" | "openai-responses" | "anthropic";
  base_url: string;
  upstream_path?: string | null;
  api_key?: string | null;
}

interface ProcessedEndpoint {
  api_type: "openai" | "openai-responses" | "anthropic";
  base_url: string;
  upstream_path: string | null;
  api_key: string | null;
}

/** 校验 endpoints 数组并加密 api_key。成功返回处理后的数组，失败返回错误信息 */
function validateAndEncryptEndpoints(
  endpoints: EndpointInput[],
  encryptionKey: string,
): { ok: true; processed: ProcessedEndpoint[] } | { ok: false; message: string } {
  const apiTypes = endpoints.map(e => e.api_type);
  if (new Set(apiTypes).size !== apiTypes.length) {
    return { ok: false, message: "endpoints 中存在重复的 api_type" };
  }
  for (const ep of endpoints) {
    if (!isValidHttpUrl(ep.base_url)) {
      return { ok: false, message: `endpoint (${ep.api_type}) base_url 格式无效，必须是以 http:// 或 https:// 开头的合法 URL` };
    }
  }
  const processed = endpoints.map(e => ({
    api_type: e.api_type,
    base_url: e.base_url,
    upstream_path: e.upstream_path ?? null,
    api_key: e.api_key ? encrypt(e.api_key, encryptionKey) : null,
  }));
  return { ok: true, processed };
}

